function design(site, analyse) {
  const X = [0, 3.9625, 7.925, 11.8875, 15.85, 19.8125, 23.775, 27.7375, 31.7];
  const F = 5.6, SP = 31.7;
  const yA = i => -4 * F * (X[i] / SP) * (1 - X[i] / SP);

  const nodes = [];
  for (let i = 1; i <= 7; i++) {
    nodes.push({ id: "A" + i, x: X[i], y: yA(i), z: -4.05, joint: "pin" });
    nodes.push({ id: "C" + i, x: X[i], y: yA(i), z: 4.05, joint: "pin" });
  }

  const M = [];
  const AL = ["L0","A1","A2","A3","A4","A5","A6","A7","L8"];
  const AR = ["R0","C1","C2","C3","C4","C5","C6","C7","R8"];
  for (let i = 0; i < 8; i++) {
    M.push({ a: AL[i], b: AL[i + 1], role: "arch" });
    M.push({ a: AR[i], b: AR[i + 1], role: "arch" });
  }
  for (let i = 0; i < 8; i++) {
    M.push({ a: "L" + i, b: "L" + (i + 1), role: "tie" });
    M.push({ a: "R" + i, b: "R" + (i + 1), role: "tie" });
  }
  for (let i = 1; i <= 7; i++) {
    M.push({ a: "L" + i, b: "A" + i, role: "hang" });
    M.push({ a: "R" + i, b: "C" + i, role: "hang" });
  }
  for (let i = 0; i <= 8; i++) M.push({ a: "L" + i, b: "R" + i, role: "beam" });
  for (let i = 1; i <= 7; i++) {
    M.push({ a: "L" + i, b: "C" + i, role: "frame" });
    M.push({ a: "R" + i, b: "A" + i, role: "frame" });
  }
  for (let i = 1; i <= 6; i++) {
    if (i <= 3) {
      M.push({ a: "L" + i, b: "A" + (i + 1), role: "diag" });
      M.push({ a: "R" + i, b: "C" + (i + 1), role: "diag" });
    } else {
      M.push({ a: "A" + i, b: "L" + (i + 1), role: "diag" });
      M.push({ a: "C" + i, b: "R" + (i + 1), role: "diag" });
    }
  }
  for (let i = 0; i < 8; i++) {
    M.push({ a: "L" + i, b: "R" + (i + 1), role: "lat" });
    M.push({ a: "R" + i, b: "L" + (i + 1), role: "lat" });
  }

  const LIST = {
    arch: ["AL7075 CHS219.1x8","AL7075 CHS244.5x8","AL7075 CHS273x10","AL7075 CHS323.9x10","AL7075 CHS355.6x12.5","AL7075 CHS406.4x12.5","AL7075 CHS457x16"],
    tie: ["AL7075 CHS139.7x6.3","AL7075 CHS168.3x6.3","AL7075 CHS193.7x6.3","AL7075 CHS193.7x8","AL7075 CHS219.1x8","AL7075 CHS244.5x8","AL7075 CHS273x10","AL7075 CHS323.9x10"],
    hang: ["AL7075 CHS88.9x5","AL7075 CHS114.3x5","AL7075 CHS139.7x5","AL7075 CHS139.7x6.3","AL7075 CHS168.3x6.3","AL7075 CHS193.7x6.3"],
    beam: ["AL7075 CHS76.1x4","AL7075 CHS88.9x5","AL7075 CHS114.3x5","AL7075 CHS139.7x5","AL7075 CHS168.3x6.3","AL7075 CHS193.7x6.3"],
    frame: ["AL7075 CHS76.1x4","AL7075 CHS88.9x5","AL7075 CHS114.3x5","AL7075 CHS139.7x5","AL7075 CHS168.3x6.3","AL7075 CHS193.7x6.3"],
    diag: ["AL7075 CHS139.7x5","AL7075 CHS168.3x6.3","AL7075 CHS193.7x8","AL7075 CHS219.1x8","AL7075 CHS244.5x8","AL7075 CHS273x10"],
    lat: ["AL7075 CHS76.1x4","AL7075 CHS88.9x5","AL7075 CHS114.3x5","AL7075 CHS139.7x5","AL7075 CHS168.3x6.3","AL7075 CHS193.7x6.3"]
  };
  const START = { arch: 2, tie: 6, hang: 3, beam: 2, frame: 2, diag: 3, lat: 2 };

  const idx = [];
  for (let i = 0; i < M.length; i++) idx.push(START[M[i].role]);

  const build = () => ({
    note: "AL7075 tied bowstring: two shallow arches below the deck edges with vertical hangers, one tension diagonal per panel and a cross-braced deck plane",
    nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
    joints: {},
    members: M.map((m, i) => ({ a: m.a, b: m.b, spec: LIST[m.role][idx[i]] }))
  });

  let calls = 0;
  const call = d => {
    if (calls >= 60) return null;
    calls++;
    try { return analyse(d); } catch (e) { return null; }
  };

  const num = (r, k) => (r && typeof r[k] === "number") ? r[k] : null;

  const uOf = (r, i) => {
    if (!r || !Array.isArray(r.members)) return 0;
    let e = null;
    if (r.members.length === M.length) e = r.members[i];
    else {
      for (const mm of r.members) {
        if (mm && mm.id !== undefined) {
          const s = String(mm.id);
          if (s === "M" + (i + 1) || s === "M" + i || s === "m" + (i + 1) || s === M[i].a + "-" + M[i].b || s === M[i].b + "-" + M[i].a) { e = mm; break; }
        }
      }
    }
    if (!e) return 0;
    return typeof e.util === "number" ? e.util : (typeof e.maxUtil === "number" ? e.maxUtil : 0);
  };

  const pass = r => !!r && (r.ok === true || (r.ok !== false && typeof r.maxUtil === "number" && r.maxUtil <= 1.0));

  const bump = (role, n) => {
    const s = n || 1;
    for (let i = 0; i < M.length; i++) if (M[i].role === role) {
      idx[i] = Math.min(LIST[role].length - 1, idx[i] + s);
    }
  };

  let res = call(build());
  if (!res || res.error) return build();

  let round = 0;
  while (round < 12 && res && !(pass(res) && (num(res, "maxUtil") === null || res.maxUtil <= 0.78))) {
    round++;
    let changed = false;
    for (let i = 0; i < M.length; i++) {
      const u = uOf(res, i);
      if (u > 0.78 && idx[i] < LIST[M[i].role].length - 1) {
        const s = u > 1.6 ? 3 : (u > 1.05 ? 2 : 1);
        idx[i] = Math.min(LIST[M[i].role].length - 1, idx[i] + s);
        changed = true;
      }
    }
    const fail = typeof res.failure === "string" ? res.failure.toLowerCase() : "";
    const badSag = (num(res, "sag") !== null && num(res, "sagLimit") !== null && res.sag > 0.85 * res.sagLimit) || /sag|deflect/.test(fail);
    const badSway = (num(res, "sway") !== null && num(res, "swayLimit") !== null && res.sway > 0.85 * res.swayLimit) || /sway|lateral/.test(fail);
    const badCr = (num(res, "alphaCr") !== null && num(res, "alphaCrMin") !== null && res.alphaCr < 1.2 * res.alphaCrMin) || /buckl|instab/.test(fail);
    const badF = (num(res, "frequency") !== null && num(res, "fMin") !== null && res.frequency < 1.15 * res.fMin) || /frequ|modal|vibrat/.test(fail);
    const badFat = (num(res, "fatigueWorst") !== null && res.fatigueWorst > 0.85) || /fatig/.test(fail);
    const badRob = /robust|cable|snap|wire/.test(fail);
    const badMech = /mechan/.test(fail);
    if (badSag) { bump("arch"); bump("tie"); changed = true; }
    if (badSway) { bump("lat"); bump("beam"); bump("frame"); changed = true; }
    if (badCr) { bump("arch"); bump("diag"); bump("lat"); changed = true; }
    if (badF) { bump("arch"); bump("tie"); changed = true; }
    if (badFat) { bump("hang"); bump("tie"); bump("diag"); changed = true; }
    if (badMech) { bump("diag"); bump("lat"); bump("frame"); changed = true; }
    if (badRob) { bump("hang"); changed = true; }
    if (!changed) {
      if (pass(res)) break;
      bump("arch"); bump("tie"); bump("diag");
    }
    res = call(build());
    if (!res || res.error) break;
  }

  let down = 0;
  while (down < 3 && res && pass(res)) {
    down++;
    const prev = idx.slice();
    let changed = false;
    for (let i = 0; i < M.length; i++) {
      if (uOf(res, i) < 0.22 && idx[i] > 0) { idx[i]--; changed = true; }
    }
    if (!changed) break;
    const r2 = call(build());
    const ok2 = r2 && pass(r2) && !r2.error &&
      (num(r2, "maxUtil") === null || r2.maxUtil <= 0.82) &&
      (num(r2, "sag") === null || num(r2, "sagLimit") === null || r2.sag < 0.9 * r2.sagLimit) &&
      (num(r2, "sway") === null || num(r2, "swayLimit") === null || r2.sway < 0.9 * r2.swayLimit) &&
      (num(r2, "frequency") === null || num(r2, "fMin") === null || r2.frequency > 1.1 * r2.fMin) &&
      (num(r2, "alphaCr") === null || num(r2, "alphaCrMin") === null || r2.alphaCr > 1.2 * r2.alphaCrMin) &&
      (num(r2, "fatigueWorst") === null || r2.fatigueWorst < 0.9);
    if (ok2) { res = r2; } else {
      for (let i = 0; i < M.length; i++) idx[i] = prev[i];
      break;
    }
  }

  return build();
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const nodes = [];
  const links = [];
  const note = "Pinned AL7075 side trusses with triangulated transverse frames and a braced lower plan, sized with a nominal-case margin search.";

  for (let i = 0; i < 9; i++) {
    nodes.push({ id: "BL" + i, x: xs[i], y: -5.35, z: -4.05, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xs[i], y: -5.35, z:  4.05, joint: "pin" });
    nodes.push({ id: "C"  + i, x: xs[i], y: -2.675, z: 0, joint: "pin" });
    nodes.push({ id: "BC" + i, x: xs[i], y: -5.35, z: 0, joint: "pin" });
  }

  function add(a, b, group) {
    links.push({ a, b, group });
  }

  for (const side of ["L", "R"]) {
    const lower = side === "L" ? "BL" : "BR";

    for (let i = 0; i < 8; i++) {
      add(side + i, side + (i + 1), "top");
      add(lower + i, lower + (i + 1), "bottom");
    }

    for (let i = 0; i < 9; i++) {
      add(side + i, lower + i, "post");
    }

    for (let i = 0; i < 8; i++) {
      let a, b;
      if (i < 4) {
        a = side + i;
        b = lower + (i + 1);
      } else {
        a = lower + i;
        b = side + (i + 1);
      }
      const group = (i === 0 || i === 7) ? "diagEnd" :
                    (i === 1 || i === 6) ? "diagNear" : "diagMid";
      add(a, b, group);
    }
  }

  for (let i = 0; i < 9; i++) {
    add("L" + i, "C" + i, "radial");
    add("R" + i, "C" + i, "radial");
    add("BL" + i, "C" + i, "radial");
    add("BR" + i, "C" + i, "radial");

    add("C" + i, "BC" + i, "stem");
    add("BL" + i, "BC" + i, "tie");
    add("BC" + i, "BR" + i, "tie");
  }

  for (let i = 0; i < 8; i++) {
    add("BC" + i, "BC" + (i + 1), "keel");
    add("BL" + i, "BC" + (i + 1), "plan");
    add("BR" + i, "BC" + (i + 1), "plan");
  }

  const options = {
    top: [
      "CHS193.7x6.3", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
      "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
    ],
    bottom: [
      "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
      "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
      "CHS323.9x10", "CHS457x16"
    ],
    post: [
      "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
      "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
      "CHS323.9x10", "CHS457x16"
    ],
    diagEnd: [
      "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS244.5x8", "CHS273x10", "CHS323.9x10",
      "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
    ],
    diagNear: [
      "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
      "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
      "CHS323.9x10", "CHS406.4x12.5", "CHS457x16"
    ],
    diagMid: [
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8",
      "CHS244.5x8", "CHS273x10", "CHS323.9x10", "CHS457x16"
    ],
    radial: [
      "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
      "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
      "CHS273x10", "CHS323.9x10", "CHS457x16"
    ],
    stem: [
      "CHS48.3x3.2", "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS323.9x10", "CHS457x16"
    ],
    tie: [
      "CHS48.3x3.2", "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS273x10", "CHS457x16"
    ],
    keel: [
      "CHS48.3x3.2", "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS273x10", "CHS457x16"
    ],
    plan: [
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8",
      "CHS244.5x8", "CHS273x10", "CHS323.9x10", "CHS457x16"
    ]
  };

  const order = [
    "stem", "tie", "keel", "plan", "radial",
    "diagMid", "diagNear", "diagEnd", "post", "bottom", "top"
  ];
  const specs = {};
  for (const g of Object.keys(options)) specs[g] = options[g][options[g].length - 1];

  function materialize() {
    return {
      note,
      nodes,
      members: links.map(m => [m.a, m.b, "AL7075 " + specs[m.group]])
    };
  }

  let calls = 0;
  function assess() {
    if (calls >= 120) return null;
    calls++;
    try {
      return analyse(materialize());
    } catch (_) {
      return null;
    }
  }

  function acceptable(r) {
    if (!r || r.error || r.ok !== true) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.62) return false;
    if (typeof r.alphaCrMin === "number" && r.alphaCrMin < 4.0) return false;

    const fmin = (typeof r.fMin === "number" && r.fMin > 0) ? r.fMin : 2.5;
    if (typeof r.frequency === "number" &&
        r.frequency < Math.max(2.8, 1.08 * fmin)) return false;

    if (typeof r.sag === "number" && typeof r.sagLimit === "number" &&
        r.sagLimit > 0 && Math.abs(r.sag) > 0.85 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" &&
        r.swayLimit > 0 && Math.abs(r.sway) > 0.85 * r.swayLimit) return false;

    return true;
  }

  const initial = assess();
  if (acceptable(initial)) {
    for (const g of order) {
      const arr = options[g];
      let lo = 0;
      let hi = arr.length - 1;
      let best = hi;

      while (lo <= hi && calls < 120) {
        const mid = Math.floor((lo + hi) / 2);
        specs[g] = arr[mid];
        const report = assess();

        if (acceptable(report)) {
          best = mid;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      specs[g] = arr[best];
    }
  }

  return materialize();
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const note = "A 5.70 m-deep pinned box truss with triangulated side webs, top and bottom plan bracing, and transverse frame diagonals; AL7075 CHS sizes are reduced using analysis margins.";
  const nodes = [];
  const links = [];

  for (let i = 0; i < 9; i++) {
    nodes.push({ id: "BL" + i, x: xs[i], y: -5.70, z: -4.05, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xs[i], y: -5.70, z:  4.05, joint: "pin" });
  }

  function add(a, b, group) {
    links.push({ a, b, group });
  }

  for (const side of ["L", "R"]) {
    const lower = side === "L" ? "BL" : "BR";

    for (let i = 0; i < 8; i++) {
      add(side + i, side + (i + 1), "top");
      add(lower + i, lower + (i + 1), "bottom");
    }

    for (let i = 0; i < 9; i++) add(side + i, lower + i, "post");

    for (let i = 0; i < 8; i++) {
      const group = (i === 0 || i === 7) ? "webEnd" :
                    (i === 1 || i === 6) ? "webNear" : "webMid";
      if (i < 4) add(side + i, lower + (i + 1), group);
      else add(lower + i, side + (i + 1), group);
    }
  }

  for (let i = 0; i < 9; i++) {
    add("L" + i, "R" + i, "topCross");
    add("BL" + i, "BR" + i, "bottomCross");

    if (i % 2 === 0) add("L" + i, "BR" + i, "frame");
    else add("R" + i, "BL" + i, "frame");
  }

  for (let i = 0; i < 8; i++) {
    if (i % 2 === 0) {
      add("L" + i, "R" + (i + 1), "topPlan");
      add("BL" + i, "BR" + (i + 1), "bottomPlan");
    } else {
      add("R" + i, "L" + (i + 1), "topPlan");
      add("BR" + i, "BL" + (i + 1), "bottomPlan");
    }
  }

  const sections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
    "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4",
    "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5",
    "CHS139.7x5", "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5",
    "CHS406.4x12.5", "CHS457x16"
  ];

  const groupOrder = [
    "topPlan", "bottomPlan", "frame", "topCross", "bottomCross",
    "post", "webMid", "webNear", "webEnd", "bottom", "top"
  ];
  const index = Object.create(null);
  for (const group of groupOrder) index[group] = sections.length - 1;

  function materialize() {
    return {
      note,
      nodes,
      members: links.map(m => [m.a, m.b, "AL7075 " + sections[index[m.group]]])
    };
  }

  let calls = 0;
  const maxCalls = 120;
  const cache = Object.create(null);

  function assess() {
    const key = groupOrder.map(g => index[g]).join(",");
    if (Object.prototype.hasOwnProperty.call(cache, key)) return cache[key];
    if (calls >= maxCalls) return null;

    calls++;
    let result = null;
    try {
      result = analyse(materialize());
    } catch (_) {
      result = null;
    }
    cache[key] = result;
    return result;
  }

  function finite(x) {
    return typeof x === "number" && isFinite(x);
  }

  function acceptable(r, t) {
    if (!r || r.error || r.ok !== true) return false;

    if (finite(r.maxUtil) && r.maxUtil > t.util) return false;

    const acr = finite(r.alphaCrMin) ? r.alphaCrMin :
                (finite(r.alphaCr) ? r.alphaCr : null);
    if (acr !== null && acr < t.alpha) return false;

    const fmin = finite(r.fMin) && r.fMin > 0 ? r.fMin : 2.5;
    if (finite(r.frequency) &&
        r.frequency < Math.max(t.frequency, t.frequencyFactor * fmin)) return false;

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        Math.abs(r.sag) > t.deflection * r.sagLimit) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        Math.abs(r.sway) > t.deflection * r.swayLimit) return false;

    if (finite(r.fatigueWorst) && r.fatigueWorst > t.fatigue) return false;
    if (r.robustness === false) return false;

    return true;
  }

  const initial = assess();
  const tiers = [
    { util: 0.62, alpha: 5.2, frequency: 2.8,  frequencyFactor: 1.08, deflection: 0.82, fatigue: 0.70 },
    { util: 0.74, alpha: 4.1, frequency: 2.65, frequencyFactor: 1.04, deflection: 0.92, fatigue: 0.82 },
    { util: 0.90, alpha: 3.2, frequency: 2.55, frequencyFactor: 1.02, deflection: 0.98, fatigue: 0.95 },
    { util: 1.00, alpha: 3.0, frequency: 2.50, frequencyFactor: 1.00, deflection: 1.00, fatigue: 1.00 }
  ];

  let tier = null;
  for (const t of tiers) {
    if (acceptable(initial, t)) {
