    let startReport = null;
    let chosenTier = null;

    for (const seed of seeds) {
      if (analyses >= MAX_ANALYSES) break;
      const r = assess(seed);
      const t = tierFor(r);
      if (!t) continue;
      if (!chosenTier || t.rank < chosenTier.rank ||
          (t.rank === chosenTier.rank && massOf(r) < massOf(startReport))) {
        start = cloneVector(topology, seed);
        startReport = r;
        chosenTier = t;
      }
    }

    if (!start) return null;

    let bestVector = cloneVector(topology, start);
    let bestReport = startReport;
    let bestMass = massOf(startReport);

    function consider(v, r) {
      if (!acceptable(r, chosenTier)) return;
      const m = massOf(r);
      if (m < bestMass) {
        bestMass = m;
        bestVector = cloneVector(topology, v);
        bestReport = r;
      }
    }

    const vector = cloneVector(topology, start);
    for (let pass = 0; pass < passes && analyses < MAX_ANALYSES; pass++) {
      for (const group of topology.groupOrder) {
        if (analyses >= MAX_ANALYSES) break;

        const current = vector[group];
        let lo = 0;
        let hi = current;
        let bestIndex = current;

        while (lo <= hi && analyses < MAX_ANALYSES) {
          const mid = Math.floor((lo + hi) / 2);
          vector[group] = mid;
          const r = assess(vector);
          if (acceptable(r, chosenTier)) {
            bestIndex = mid;
            hi = mid - 1;
            consider(vector, r);
          } else {
            lo = mid + 1;
          }
        }

        vector[group] = bestIndex;
        const finalReport = assess(vector);
        if (acceptable(finalReport, chosenTier)) {
          consider(vector, finalReport);
        } else {
          vector[group] = current;
        }
      }
    }

    return {
      rank: chosenTier.rank,
      mass: bestMass,
      report: bestReport,
      vector: bestVector,
      topology,
      design: materialize(topology, bestVector)
    };
  }

  const candidates = [
    { topology: makeTopology("down8", "down", 8), passes: 2 },
    { topology: makeTopology("up8out", "up", 8), passes: 1 },
    { topology: makeTopology("down6", "down", 6), passes: 1 }
  ];

  const results = [];
  let best = null;

  for (const item of candidates) {
    if (analyses >= MAX_ANALYSES) break;
    const result = optimize(item.topology, item.passes);
    if (!result) continue;
    results.push(result);
    if (better(result.rank, result.mass, best)) best = result;
  }

  function tryIPE(base, groups) {
    if (!base || analyses >= MAX_ANALYSES) return;
    const selected = Object.create(null);
    let found = false;
    for (const g of groups) {
      if (base.topology.groupOrder.indexOf(g) >= 0) {
        selected[g] = "AL6082 IPE450";
        found = true;
      }
    }
    if (!found) return;

    const members = base.topology.links.map((m, i) => [
      m.a, m.b,
      selected[m.group] ? selected[m.group] : base.design.members[i][2]
    ]);
    const candidate = { note, nodes: base.topology.nodes, members };
    const r = runAnalysis(candidate);
    const t = tierFor(r);
    if (!t) return;

    const mass = massOf(r);
    if (better(t.rank, mass, best)) {
      best = {
        rank: t.rank,
        mass,
        report: r,
        topology: base.topology,
        design: candidate
      };
    }
  }

  const replacementSets = [
    ["topE"], ["topN"], ["topM"],
    ["topE", "topN", "topM"],
    ["bottomE"], ["bottomN"], ["bottomM"],
    ["bottomE", "bottomN", "bottomM"]
  ];

  for (const result of results) {
    for (const groups of replacementSets) {
      if (analyses >= MAX_ANALYSES) break;
      tryIPE(result, groups);
    }
  }

  if (best) {
    best.design.note = note;
    return best.design;
  }

  const fallback = makeTopology("down8", "down", 8);
  return materialize(fallback, knownDownVector(fallback));
}

function design(site, analyse) {
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const span = 31.7;
  const halfWidth = 4.05;

  // Ordered by area so section reductions are monotone.
  const sections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
    "CHS60.3x3.2", "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4",
    "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5",
    "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8",
    "CHS244.5x8", "CHS273x10", "CHS323.9x10",
    "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];
  const areas = [
    2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18,
    13.86, 17.17, 21.16, 25.65, 32.06, 37.09, 46.67, 53.06,
    59.44, 82.62, 98.61, 134.74, 154.68, 221.67
  ];
  const sectionIndex = Object.create(null);
  for (let i = 0; i < sections.length; i++) sectionIndex[sections[i]] = i;

  const note =
    "A pinned AL7075 CHS box truss uses a deep under-deck triangulated web and analysis-driven sizing with reserve for unit variation.";

  const MAX_CALLS = 380;
  const GROUP_LIMIT = 260;
  let calls = 0;

  const tiers = [
    { rank: 0, util: 0.70, alpha: 8.0, frequency: 2.85, deflection: 0.85, fatigue: 0.70 },
    { rank: 1, util: 0.77, alpha: 6.0, frequency: 2.70, deflection: 0.90, fatigue: 0.77 },
    { rank: 2, util: 0.84, alpha: 5.0, frequency: 2.58, deflection: 0.95, fatigue: 0.84 },
    { rank: 3, util: 0.90, alpha: 4.0, frequency: 2.56, deflection: 0.98, fatigue: 0.92 },
    { rank: 4, util: 0.97, alpha: 3.2, frequency: 2.52, deflection: 1.00, fatigue: 0.98 },
    { rank: 5, util: 1.00, alpha: 3.0, frequency: 2.50, deflection: 1.00, fatigue: 1.00 }
  ];

  const groupPriority = [
    "topPlan", "bottomPlan", "frame", "topCross", "bottomCross",
    "webEnd", "webNear", "webMid",
    "postEnd", "postNear", "postMid",
    "bottomE", "bottomN", "bottomM",
    "topE", "topN", "topM"
  ];

  const knownNames = {
    topE: "CHS406.4x12.5", topN: "CHS406.4x12.5", topM: "CHS406.4x12.5",
    bottomE: "CHS406.4x12.5", bottomN: "CHS406.4x12.5", bottomM: "CHS406.4x12.5",
    postEnd: "CHS114.3x4", postNear: "CHS355.6x12.5", postMid: "CHS193.7x8",
    webEnd: "CHS355.6x12.5", webNear: "CHS168.3x6.3", webMid: "CHS139.7x5",
    topCross: "CHS114.3x4", bottomCross: "CHS168.3x5",
    frame: "CHS168.3x6.3", topPlan: "CHS219.1x8",
    bottomPlan: "CHS193.7x6.3"
  };

  const tunedNames = {
    topE: "CHS406.4x12.5", topN: "CHS406.4x12.5", topM: "CHS406.4x12.5",
    bottomE: "CHS406.4x12.5", bottomN: "CHS406.4x12.5", bottomM: "CHS406.4x12.5",
    postEnd: "CHS323.9x10", postNear: "CHS244.5x8", postMid: "CHS193.7x8",
    webEnd: "CHS323.9x10", webNear: "CHS244.5x8", webMid: "CHS139.7x5",
    topCross: "CHS114.3x5", bottomCross: "CHS168.3x6.3",
    frame: "CHS168.3x5", topPlan: "CHS219.1x8",
    bottomPlan: "CHS193.7x6.3"
  };

  function finite(x) {
    return typeof x === "number" && isFinite(x);
  }

  function massOf(r) {
    return r && finite(r.mass) ? r.mass : Infinity;
  }

  function pairKey(a, b) {
    return a < b ? a + "\u0001" + b : b + "\u0001" + a;
  }

  function reportMeets(r, tier) {
    if (!r || r.error || r.ok !== true || r.robustness === false) return false;
    if (finite(r.maxUtil) && r.maxUtil > tier.util) return false;

    const alpha = finite(r.alphaCrMin) ? r.alphaCrMin :
                  (finite(r.alphaCr) ? r.alphaCr : null);
    if (alpha !== null && alpha < tier.alpha) return false;

    const fmin = finite(r.fMin) && r.fMin > 0 ? r.fMin : 2.5;
    if (finite(r.frequency) &&
        r.frequency < Math.max(tier.frequency, fmin)) return false;

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        Math.abs(r.sag) > tier.deflection * r.sagLimit) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        Math.abs(r.sway) > tier.deflection * r.swayLimit) return false;
    if (finite(r.fatigueWorst) && r.fatigueWorst > tier.fatigue) return false;
    return true;
  }

  function cloneMap(v, keys) {
    const out = Object.create(null);
    for (const k of keys) out[k] = v[k];
    return out;
  }

  function makeTopology(nBottom, frameMode) {
    const nodes = [];
    const links = [];
    const coords = Object.create(null);
    const seen = Object.create(null);
    const bottomXs = nBottom === 8
      ? xs.slice()
      : Array.from({ length: nBottom + 1 }, (_, i) => span * i / nBottom);

    function topId(side, i) {
      return side + i;
    }

    function bottomId(side, i) {
      return "B" + side + i;
    }

    for (const side of ["L", "R"]) {
      const z = side === "L" ? -halfWidth : halfWidth;
      for (let i = 0; i <= 8; i++) {
        coords[topId(side, i)] = { x: xs[i], y: 0, z: z };
      }
      for (let i = 0; i <= nBottom; i++) {
        const id = bottomId(side, i);
        nodes.push({
          id: id, x: bottomXs[i], y: -5.70, z: z, joint: "pin"
        });
        coords[id] = { x: bottomXs[i], y: -5.70, z: z };
      }
    }

    function add(a, b, group) {
      if (a === b || !coords[a] || !coords[b]) return;
      const key = pairKey(a, b);
      if (seen[key]) return;
      const p = coords[a];
      const q = coords[b];
      const dx = p.x - q.x;
      const dy = p.y - q.y;
      const dz = p.z - q.z;
      const length = Math.sqrt(dx * dx + dy * dy + dz * dz);
      if (length < 0.4 || length > 12.0) return;
      seen[key] = true;
      links.push({ a: a, b: b, group: group, length: length });
    }

    function chordGroup(role, i, n) {
      const d = Math.min(i, n - 1 - i);
      return role + (d === 0 ? "E" : (d === 1 ? "N" : "M"));
    }

    function webGroupAtX(x) {
      const d = Math.min(x, span - x);
      return d < 2.5 ? "webEnd" : (d < 11.6 ? "webNear" : "webMid");
    }

    function postGroupAtX(x) {
      const d = Math.min(x, span - x);
      return d < 1e-6 ? "postEnd" : (d <= 8.0 ? "postNear" : "postMid");
    }

    for (const side of ["L", "R"]) {
      for (let i = 0; i < 8; i++) {
        add(topId(side, i), topId(side, i + 1), chordGroup("top", i, 8));
      }
      for (let i = 0; i < nBottom; i++) {
        add(bottomId(side, i), bottomId(side, i + 1),
            chordGroup("bottom", i, nBottom));
      }

      add(topId(side, 0), bottomId(side, 0), "postEnd");

      let i = 0;
      let j = 0;
      while (i < 8 || j < nBottom) {
        const nextTop = i < 8 ? xs[i + 1] : Infinity;
        const nextBottom = j < nBottom ? bottomXs[j + 1] : Infinity;

        if (Math.abs(nextTop - nextBottom) < 1e-7) {
          const ni = i + 1;
          const nj = j + 1;
          const midX = 0.5 * (xs[i] + bottomXs[nj]);
          add(topId(side, i), bottomId(side, nj), webGroupAtX(midX));
          add(topId(side, ni), bottomId(side, nj), postGroupAtX(bottomXs[nj]));
          i = ni;
          j = nj;
        } else if (nextTop < nextBottom) {
          const midX = 0.5 * (bottomXs[j] + nextTop);
          add(bottomId(side, j), topId(side, i + 1), webGroupAtX(midX));
          i++;
        } else {
          const midX = 0.5 * (xs[i] + nextBottom);
          add(topId(side, i), bottomId(side, j + 1), webGroupAtX(midX));
          j++;
        }
      }
    }

    for (let i = 0; i <= 8; i++) {
      add(topId("L", i), topId("R", i), "topCross");
    }
    for (let i = 0; i <= nBottom; i++) {
      add(bottomId("L", i), bottomId("R", i), "bottomCross");
    }

    if (frameMode !== 0) {
      const active = Object.create(null);
      if (frameMode === 2) {
        for (let i = 0; i <= nBottom; i++) active[i] = true;
      } else {
        active[0] = true;
        active[nBottom] = true;
        active[Math.floor(nBottom / 2)] = true;
        active[Math.ceil(nBottom / 2)] = true;
      }

      function nearestTopIndex(x) {
        let best = 0;
        let error = Infinity;
        for (let i = 0; i <= 8; i++) {
          const e = Math.abs(xs[i] - x);
          if (e < error) {
            error = e;
            best = i;
          }
        }
        return best;
      }

      for (let i = 0; i <= nBottom; i++) {
        if (!active[i]) continue;
        const k = nearestTopIndex(bottomXs[i]);
        if (i % 2 === 0) {
          add(topId("L", k), bottomId("R", i), "frame");
        } else {
          add(topId("R", k), bottomId("L", i), "frame");
        }
      }
    }

    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) {
        add(topId("L", i), topId("R", i + 1), "topPlan");
      } else {
        add(topId("R", i), topId("L", i + 1), "topPlan");
      }
    }
    for (let i = 0; i < nBottom; i++) {
      if (i % 2 === 0) {
        add(bottomId("L", i), bottomId("R", i + 1), "bottomPlan");
      } else {
        add(bottomId("R", i), bottomId("L", i + 1), "bottomPlan");
      }
    }

    const used = Object.create(null);
    for (const m of links) used[m.group] = true;
    const groupOrder = groupPriority.filter(g => used[g]);

    return {
      name: "down" + nBottom + "_f" + frameMode,
      nodes: nodes,
      links: links,
      groupOrder: groupOrder,
      cache: Object.create(null)
    };
  }

  function materialize(topology, memberLevels) {
    const members = topology.links.map((m, i) => [
      m.a, m.b, "AL7075 " + sections[memberLevels[i]]
    ]);
    return { note: note, nodes: topology.nodes, members: members };
  }

  function evaluateMembers(topology, memberLevels, limit) {
    const key = memberLevels.join(",");
    if (Object.prototype.hasOwnProperty.call(topology.cache, key)) {
      return topology.cache[key];
    }
    if (calls >= limit) return null;
    calls++;
    let r = null;
    try {
      r = analyse(materialize(topology, memberLevels));
    } catch (_) {
      r = null;
    }
    topology.cache[key] = r;
    return r;
  }

  function evaluateGroups(topology, groupLevels, limit) {
    const memberLevels = topology.links.map(m => groupLevels[m.group]);
    return evaluateMembers(topology, memberLevels, limit);
  }

  function vectorFromNames(topology, names) {
    const v = Object.create(null);
    for (const g of topology.groupOrder) {
      const name = names[g] || "CHS323.9x10";
      v[g] = sectionIndex[name] === undefined
        ? sectionIndex["CHS323.9x10"]
        : sectionIndex[name];
    }
    return v;
  }

  function uniformVector(topology, name) {
    const v = Object.create(null);
    const index = sectionIndex[name];
    for (const g of topology.groupOrder) v[g] = index;
    return v;
  }

  function betterCandidate(a, b) {
    if (!b) return true;
    if (a.tier.rank !== b.tier.rank) return a.tier.rank < b.tier.rank;
    return massOf(a.report) < massOf(b.report);
  }

  const topologies = [
    makeTopology(4, 2),
    makeTopology(5, 2),
    makeTopology(6, 2),
    makeTopology(7, 2),
    makeTopology(8, 2),
    makeTopology(6, 1),
    makeTopology(6, 0)
  ];

  const candidates = [];
  let fallbackRaw = null;

  for (const topology of topologies) {
    const seedVectors = [
      uniformVector(topology, "CHS323.9x10"),
      uniformVector(topology, "CHS355.6x12.5"),
      uniformVector(topology, "CHS406.4x12.5"),
      uniformVector(topology, "CHS457x16"),
      vectorFromNames(topology, knownNames),
      vectorFromNames(topology, tunedNames)
    ];

    const tested = [];
    for (const v of seedVectors) {
      const report = evaluateGroups(topology, v, MAX_CALLS);
      if (!report || report.ok !== true || report.robustness === false) continue;

      const rec = {
        topology: topology,
        vector: cloneMap(v, topology.groupOrder),
        report: report
      };
      tested.push(rec);

      if (!fallbackRaw || massOf(report) < massOf(fallbackRaw.report)) {
        fallbackRaw = rec;
      }
    }

    let selected = null;
    for (let ti = 2; ti < tiers.length && !selected; ti++) {
      const tier = tiers[ti];
      for (const rec of tested) {
        if (!reportMeets(rec.report, tier)) continue;
        if (!selected || massOf(rec.report) < massOf(selected.report)) {
          selected = {
            topology: topology,
            vector: cloneMap(rec.vector, topology.groupOrder),
            report: rec.report,
            tier: tier
          };
        }
      }
    }
    if (selected) candidates.push(selected);
  }

  function optimizeGroups(candidate) {
    const topology = candidate.topology;
    const v = cloneMap(candidate.vector, topology.groupOrder);
    let report = candidate.report;

    for (const g of topology.groupOrder) {
      if (calls >= GROUP_LIMIT) break;
      const current = v[g];
      if (current <= 0) continue;

      let lo = 0;
      let hi = current - 1;
      let best = current;
      let bestReport = report;

      while (lo <= hi && calls < GROUP_LIMIT) {
        const mid = Math.floor((lo + hi) / 2);
        const trial = cloneMap(v, topology.groupOrder);
        trial[g] = mid;
        const r = evaluateGroups(topology, trial, GROUP_LIMIT);
        if (r === null) break;

        if (reportMeets(r, candidate.tier)) {
          best = mid;
          bestReport = r;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (best < current) {
        v[g] = best;
        report = bestReport;
      }
    }

    return {
      topology: topology,
      vector: v,
      report: report,
      tier: candidate.tier
    };
  }

  candidates.sort((a, b) =>
    a.tier.rank - b.tier.rank || massOf(a.report) - massOf(b.report)
  );

  const grouped = [];
  for (const c of candidates) {
    if (calls >= GROUP_LIMIT) break;
    grouped.push(optimizeGroups(c));
  }

  let best = null;
  for (const c of candidates) {
    if (betterCandidate(c, best)) best = c;
  }
  for (const c of grouped) {
    if (betterCandidate(c, best)) best = c;
  }

  function makeFromGroups(topology, groupLevels) {
    const memberLevels = topology.links.map(m => groupLevels[m.group]);
    return materialize(topology, memberLevels);
  }

  if (!best) {
    if (fallbackRaw) {
      return makeFromGroups(fallbackRaw.topology, fallbackRaw.vector);
    }
    const fallbackTopology = topologies[2];
    return makeFromGroups(
      fallbackTopology,
      uniformVector(fallbackTopology, "CHS457x16")
    );
  }

  const topology = best.topology;
  const memberLevels = topology.links.map(m => best.vector[m.group]);
  let currentReport = best.report;

  // Spend the remaining analyses on lightly loaded individual members.
  const utilByPair = Object.create(null);
  if (currentReport && Array.isArray(currentReport.members)) {
    for (const rec of currentReport.members) {
      if (!rec || rec.id === undefined) continue;
      const id = String(rec.id);
      const dash = id.indexOf("-");
      if (dash <= 0 || dash === id.length - 1) continue;
      const a = id.slice(0, dash);
      const b = id.slice(dash + 1);
      if (finite(rec.util)) utilByPair[pairKey(a, b)] = rec.util;
    }
  }

  const memberOrder = topology.links.map((m, i) => i);
  memberOrder.sort((ia, ib) => {
    const ma = topology.links[ia];
    const mb = topology.links[ib];
    const ka = pairKey(ma.a, ma.b);
    const kb = pairKey(mb.a, mb.b);
    const ua = Object.prototype.hasOwnProperty.call(utilByPair, ka) ? utilByPair[ka] : 0.5;
    const ub = Object.prototype.hasOwnProperty.call(utilByPair, kb) ? utilByPair[kb] : 0.5;
    if (ua !== ub) return ua - ub;
    return areas[memberLevels[ib]] * mb.length -
           areas[memberLevels[ia]] * ma.length;
  });

  for (const i of memberOrder) {
    if (calls >= MAX_CALLS) break;
    const current = memberLevels[i];
    if (current <= 0) continue;

    let lo = 0;
    let hi = current - 1;
    let bestLevel = current;
    let bestReport = currentReport;

    while (lo <= hi && calls < MAX_CALLS) {
      const mid = Math.floor((lo + hi) / 2);
      const trial = memberLevels.slice();
      trial[i] = mid;
      const r = evaluateMembers(topology, trial, MAX_CALLS);
      if (r === null) break;

      if (reportMeets(r, best.tier)) {
        bestLevel = mid;
        bestReport = r;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }

    if (bestLevel < current) {
      memberLevels[i] = bestLevel;
      currentReport = bestReport;
    }
  }

  return materialize(topology, memberLevels);
}

