      } else {
        add("R" + i, "L" + (i + 1), "topPlan");
      }
    }

    if (cfg.kind !== "central") {
      for (let i = 0; i < cfg.n; i++) {
        if (i % 2 === 0) {
          add(lowerBySide.L[i], lowerBySide.R[i + 1], "bottomPlan");
        } else {
          add(lowerBySide.R[i], lowerBySide.L[i + 1], "bottomPlan");
        }
      }
    }

