    if (finite(report.maxUtil) && report.maxUtil > tier.util) return false;

    const alpha = finite(report.alphaCrMin) ? report.alphaCrMin :
                  (finite(report.alphaCr) ? report.alphaCr : null);
    if (alpha !== null && alpha < tier.alpha) return false;

    const fmin = finite(report.fMin) && report.fMin > 0 ? report.fMin : 2.5;
    const frequency = finite(report.frequency) ? report.frequency : fmin;
    if (frequency < Math.max(tier.frequency, fmin)) return false;

    if (finite(report.sag) && finite(report.sagLimit) && report.sagLimit > 0 &&
        Math.abs(report.sag) > tier.deflection * report.sagLimit) return false;
    if (finite(report.sway) && finite(report.swayLimit) && report.swayLimit > 0 &&
        Math.abs(report.sway) > tier.deflection * report.swayLimit) return false;

    if (finite(report.fatigueWorst) &&
        report.fatigueWorst > tier.fatigue) return false;
