      if (meets(report, tier)) return tier;
    }
    return null;
  }

  function cloneVector(topology, vector) {
    const result = Object.create(null);
    for (const group of topology.groupOrder) result[group] = vector[group];
    return result;
  }

  function vectorFor(topology, shift, uniform) {
    const result = Object.create(null);
    for (const group of topology.groupOrder) {
      const base = Object.prototype.hasOwnProperty.call(baseLevels, group)
        ? baseLevels[group] : 17;
