      groupWeight(topology, vector, b) - groupWeight(topology, vector, a)
    );

    for (const group of orderedGroups) {
      if (calls - startCalls >= callCap || calls >= MAX_CALLS) break;

      const current = vector[group];
      if (current <= 0) continue;

      let lo = 0;
      let hi = current - 1;
      let bestLevel = current;
      let bestReport = report;

      while (lo <= hi && calls - startCalls < callCap && calls < MAX_CALLS) {
