        const saveB = (areas[lb] - areas[lb - 1]) * mb.length;
        return saveB - saveA;
      });

      const nextActive = [];
      for (const i of active) {
        if (calls - startCalls >= callCap || calls >= MAX_CALLS) break;
        if (levels[i] <= 0) continue;

        const trial = levels.slice();
        trial[i]--;
        const r = evaluateMembers(topology, trial);

        if (r !== null && meets(r, candidate.tier)) {
          levels[i]--;
          report = r;
          nextActive.push(i);
        }
      }

      if (nextActive.length === 0) break;
      active = nextActive;
    }

