  }

  const configs = [
    { n: 4, q: 4.05, frame: 2 },
    { n: 5, q: 4.05, frame: 2 },
    { n: 6, q: 4.05, frame: 2 },
    { n: 7, q: 4.05, frame: 2 },
    { n: 8, q: 4.05, frame: 2 },
    { n: 4, q: 2.65, frame: 2 },
    { n: 6, q: 3.20, frame: 2 },
    { n: 4, q: 4.05, frame: 1 },
    { n: 6, q: 4.05, frame: 1 }
