      const report = evaluateGroups(topology, vector);

      if (report && report.ok === true && report.robustness !== false) {
        const raw = {
          topology,
          vector: cloneVector(topology, vector),
          report
        };
        if (!fallbackRaw || massOf(report) < massOf(fallbackRaw.report)) {
          fallbackRaw = raw;
        }

        const tier = tierFor(report);
        if (tier) {
          const rec = {
            topology,
            vector: cloneVector(topology, vector),
            report,
            tier
          };
          if (better(rec, localBest)) localBest = rec;
        }
      }
    }

    if (calls < MAX_CALLS) {
      const vector = vectorFor(topology, 0, true);
      const report = evaluateGroups(topology, vector);

      if (report && report.ok === true && report.robustness !== false) {
        const raw = {
          topology,
          vector: cloneVector(topology, vector),
          report
        };
        if (!fallbackRaw || massOf(report) < massOf(fallbackRaw.report)) {
          fallbackRaw = raw;
        }

        const tier = tierFor(report);
        if (tier) {
          const rec = {
            topology,
            vector: cloneVector(topology, vector),
            report,
            tier
