      return materialize(fallbackRaw.topology, levels);
    }
    const topology = topologies[0];
    const vector = vectorFor(topology, 0, true);
    return materialize(topology, topology.links.map(m => vector[m.group]));
  }

  const grouped = [];
  for (let i = 0; i < Math.min(3, candidates.length); i++) {
    if (calls >= MAX_CALLS) break;
    const optimized = optimizeGroups(candidates[i], 50);
    if (meets(optimized.report, optimized.tier)) grouped.push(optimized);
  }

  const groupedByName = Object.create(null);
  for (const rec of grouped) groupedByName[rec.topology.name] = rec;

  const finalists = candidates.map(rec =>
    groupedByName[rec.topology.name] || rec
  );
  finalists.sort(compareRecords);

  const memberCandidates = Math.min(2, finalists.length);
  if (memberCandidates > 0) {
    const perCandidateCap = Math.floor(
      Math.max(0, MAX_CALLS - calls) / memberCandidates
    );

    for (let i = 0; i < memberCandidates; i++) {
      if (perCandidateCap <= 0 || calls >= MAX_CALLS) break;
      finalists[i] = optimizeMembers(finalists[i], perCandidateCap);
    }
  }

  finalists.sort(compareRecords);
  const best = finalists[0];
