      report.ok === true && report.robustness !== false;
  }

  function meets(report, tier) {
    if (!validReport(report)) return false;

    if (finite(report.maxUtil) && report.maxUtil > tier.util) return false;

    const alpha = finite(report.alphaCrMin) ? report.alphaCrMin :
      (finite(report.alphaCr) ? report.alphaCr : null);
    if (alpha !== null && alpha < tier.alpha) return false;

    const fmin = finite(report.fMin) && report.fMin > 0 ? report.fMin : 2.5;
    const frequency = finite(report.frequency) ? report.frequency : fmin;
    if (frequency < Math.max(tier.frequency, fmin)) return false;

    if (finite(report.sag) && finite(report.sagLimit) && report.sagLimit > 0 &&
        Math.abs(report.sag) > tier.deflection * report.sagLimit) return false;
    if (finite(report.sway) && finite(report.swayLimit) && report.swayLimit > 0 &&
        Math.abs(report.sway) > tier.deflection * report.swayLimit) return false;

    if (finite(report.fatigueWorst) && report.fatigueWorst > tier.fatigue) return false;
    return true;
  }

  function tierFor(report) {
    for (const tier of tiers) {
      if (meets(report, tier)) return tier;
    }
    return null;
  }

  function massOf(report) {
    return report && finite(report.mass) ? report.mass : Infinity;
  }

  function better(a, b) {
    if (!b) return true;
    if (a.tier.rank !== b.tier.rank) return a.tier.rank < b.tier.rank;
    return massOf(a.report) < massOf(b.report);
  }

  function compareRecords(a, b) {
    if (a.tier.rank !== b.tier.rank) return a.tier.rank - b.tier.rank;
    const ma = massOf(a.report);
    const mb = massOf(b.report);
    return ma < mb ? -1 : (ma > mb ? 1 : 0);
  }

  function cloneVector(topology, vector) {
    const result = Object.create(null);
    for (const g of topology.groupOrder) result[g] = vector[g];
    return result;
  }

  function initialVector(topology, shift) {
    const result = Object.create(null);
    for (const g of topology.groupOrder) {
      const base = Object.prototype.hasOwnProperty.call(baseLevels, g)
        ? baseLevels[g] : 17;
      result[g] = Math.min(sections.length - 1, base + shift);
    }
    return result;
  }

  function groupWeight(topology, vector, group) {
    const level = vector[group];
    if (!finite(level) || level < 0) return 0;
    let weight = 0;
    for (const m of topology.links) {
      if (m.group === group) weight += areas[level] * m.length;
    }
    return weight;
  }

  function optimizeGroups(candidate, callCap) {
    const topology = candidate.topology;
    const startCalls = calls;
    const vector = cloneVector(topology, candidate.vector);
    let report = candidate.report;

    const order = topology.groupOrder.slice().sort((a, b) =>
      groupWeight(topology, vector, b) - groupWeight(topology, vector, a)
    );

    for (const group of order) {
      if (calls - startCalls >= callCap || calls >= MAX_CALLS) break;

      const current = vector[group];
      if (!finite(current) || current <= 0) continue;

      let lo = 0;
      let hi = current - 1;
      let bestLevel = current;
      let bestReport = report;

      while (lo <= hi && calls - startCalls < callCap && calls < MAX_CALLS) {
        const mid = Math.floor((lo + hi) / 2);
        const trial = cloneVector(topology, vector);
        trial[group] = mid;
        const trialReport = evaluateGroups(topology, trial);
        if (trialReport === null) break;

        if (meets(trialReport, candidate.tier)) {
          bestLevel = mid;
          bestReport = trialReport;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (bestLevel < current) {
        vector[group] = bestLevel;
        report = bestReport;
      }
    }

    return { topology, vector, report, tier: candidate.tier };
  }

  function utilityMap(report) {
    const result = Object.create(null);
    if (!report || !Array.isArray(report.members)) return result;

    for (const rec of report.members) {
      if (!rec || rec.id === undefined || !finite(rec.util)) continue;
      const id = String(rec.id);
      const dash = id.indexOf("-");
      if (dash <= 0 || dash === id.length - 1) continue;
      result[pairKey(id.slice(0, dash), id.slice(dash + 1))] = rec.util;
    }
    return result;
  }

  function levelsOf(record) {
    if (Array.isArray(record.levels)) return record.levels;
    return record.topology.links.map(m => record.vector[m.group]);
  }

  function optimizeMembers(candidate, callCap) {
    const topology = candidate.topology;
    const startCalls = calls;
    const levels = levelsOf(candidate).slice();
    let report = candidate.report;
    const utilities = utilityMap(report);
    const order = topology.links.map((_, i) => i);

    order.sort((ia, ib) => {
      const la = levels[ia];
      const lb = levels[ib];
      if (la < 0) return lb < 0 ? 0 : 1;
      if (lb < 0) return -1;

      const ma = topology.links[ia];
      const mb = topology.links[ib];
      const ua = finite(utilities[pairKey(ma.a, ma.b))
        ? utilities[pairKey(ma.a, ma.b)] : 0.55;
      const ub = finite(utilities[pairKey(mb.a, mb.b))
        ? utilities[pairKey(mb.a, mb.b)] : 0.55;
      const sa = areas[la] * ma.length * (1.05 - Math.min(1, Math.max(0, ua)));
      const sb = areas[lb] * mb.length * (1.05 - Math.min(1, Math.max(0, ub)));
      return sb - sa;
    });

    for (const i of order) {
      if (calls - startCalls >= callCap || calls >= MAX_CALLS) break;

      const current = levels[i];
      if (!finite(current) || current < 0) continue;

      let lo = -1;
      let hi = current - 1;
      let bestLevel = current;
      let bestReport = report;

      while (lo <= hi && calls - startCalls < callCap && calls < MAX_CALLS) {
        const mid = Math.floor((lo + hi) / 2);
        const trial = levels.slice();
        trial[i] = mid;
        const trialReport = evaluateMembers(topology, trial);
        if (trialReport === null) break;

        if (meets(trialReport, candidate.tier)) {
          bestLevel = mid;
          bestReport = trialReport;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (bestLevel < current) {
        levels[i] = bestLevel;
        report = bestReport;
      }
    }

    return { topology, levels, report, tier: candidate.tier };
  }

  function dedupeByTopology(records) {
    const byName = Object.create(null);
    for (const record of records) {
      const name = record.topology.name;
      if (!byName[name] || better(record, byName[name])) byName[name] = record;
    }
    return Object.keys(byName).map(name => byName[name]);
  }

  const configs = [
    { mode: "under", n: 4, q: 4.05, frame: 2 },
    { mode: "under", n: 6, q: 4.05, frame: 2 },
    { mode: "under", n: 8, q: 4.05, frame: 2 },
    { mode: "under", n: 4, q: 4.05, frame: 1 },
    { mode: "under", n: 4, q: 2.65, frame: 2 },
    { mode: "under", n: 4, q: 4.40, frame: 2 },
    { mode: "under", n: 5, q: 4.80, frame: 2 },
    { mode: "under", n: 6, q: 5.10, frame: 2 },
    { mode: "elevated", n: 6, frame: 0 },
    { mode: "elevated", n: 8, frame: 0 },
    { mode: "central", n: 4, frame: 0 },
    { mode: "central", n: 5, frame: 0 }
  ];

  const topologies = configs.map(makeTopology);
  const candidates = [];
  let fallback = null;

  function saveFallback(topology, levels, report) {
    if (!validReport(report)) return;
    if (!fallback || massOf(report) < massOf(fallback.report)) {
      fallback = { topology, levels: levels.slice(), report };
    }
  }

  for (const topology of topologies) {
    if (calls >= MAX_CALLS) break;

    let localBest = null;
    for (const shift of [0, 1, 2, 4, 8]) {
      if (calls >= MAX_CALLS) break;

      const vector = initialVector(topology, shift);
      const levels = topology.links.map(m => vector[m.group]);
      const report = evaluateMembers(topology, levels);

      saveFallback(topology, levels, report);

      const tier = tierFor(report);
      if (!tier) continue;

      const record = {
        topology,
        vector: cloneVector(topology, vector),
        report,
        tier
      };
      if (better(record, localBest)) localBest = record;
      if (tier.rank === 0) break;
    }

    if (localBest) candidates.push(localBest);
  }

  candidates.sort(compareRecords);

  const working = candidates.slice();
  for (const candidate of candidates.slice(0, 3)) {
    if (calls >= MAX_CALLS) break;
    const optimized = optimizeGroups(candidate, 32);
    if (meets(optimized.report, optimized.tier)) working.push(optimized);
  }

  let finalists = dedupeByTopology(working);
  finalists.sort(compareRecords);

  const memberStarts = finalists.slice(0, Math.min(2, finalists.length));
  if (memberStarts.length > 0) {
    const perCandidateCap = Math.floor(
      Math.max(0, MAX_CALLS - calls) / memberStarts.length
    );

    for (const candidate of memberStarts) {
      if (calls >= MAX_CALLS || perCandidateCap <= 0) break;
      const optimized = optimizeMembers(candidate, perCandidateCap);
      if (meets(optimized.report, optimized.tier)) working.push(optimized);
    }
  }

  finalists = dedupeByTopology(working);
  finalists.sort(compareRecords);

  if (finalists.length > 0) {
    return materialize(finalists[0].topology, levelsOf(finalists[0]));
  }

  if (!fallback && topologies.length > 0 && calls < MAX_CALLS) {
    const topology = topologies[0];
    const levels = topology.links.map(() => sections.length - 1);
    const report = evaluateMembers(topology, levels);
    fallback = { topology, levels, report };
  }

  if (fallback) return materialize(fallback.topology, fallback.levels);

  const topology = topologies[0];
  return materialize(
    topology,
    topology.links.map(() => sections.length - 1)
  );
}

