      "S460 CHS219.1x8",
      "S460 CHS244.5x8",
      "S460 CHS273x10",
      "S460 CHS323.9x10"
    ]
  };

  const groupNames = Object.keys(cand);
  const gIndex = {};
  groupNames.forEach((g, i) => { gIndex[g] = i; });

  function makeDesign(idx) {
    const spec = {};
    for (let i = 0; i < groupNames.length; i++) {
      const g = groupNames[i];
      spec[g] = cand[g][idx[i]];
    }
    return {
      note: "Pinned through-truss box: two 8 m deep side trusses, top/bottom cross-diagonals, and end diaphragms; section search with safety margins.",
      nodes: nodes,
      members: defs.map(d => [d.a, d.b, spec[d.g]])
    };
  }

  const cache = new Map();
  let calls = 0;
  const callLimit = 390;

  function evalIdx(idx) {
    const key = idx.join(",");
    if (cache.has(key)) return cache.get(key);
    if (calls >= callLimit) return null;
    calls++;
    let rec = { idx: idx.slice() };
    try {
      rec.design = makeDesign(idx);
      rec.r = analyse(rec.design);
    } catch (e) {
      rec.r = { ok: false, error: String(e) };
    }
    cache.set(key, rec);
    return rec;
  }

  function passes(r, th) {
    if (!r || !r.ok) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > th.u) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < th.a) return false;
    if (typeof r.frequency === "number" && r.frequency < th.f) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > th.sag * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > th.sway * r.swayLimit) return false;
    if (r.robustness === false) return false;
    if (typeof r.robustness === "string" && /fail|false|no/i.test(r.robustness)) return false;
    return true;
  }

  const maxIdx = groupNames.map(g => cand[g].length - 1);

  function optimize(th, order) {
    let cur = maxIdx.slice();
    let rec = evalIdx(cur);
    if (!rec || !passes(rec.r, th)) return null;
    let best = rec;

    for (let pass = 0; pass < 4; pass++) {
      let changed = false;
      for (let oi = 0; oi < order.length; oi++) {
        const gi = order[oi];
        const hi = cur[gi];
        if (hi <= 0) continue;

        let found = -1;
        let test = cur.slice();
        test[gi] = 0;
        let r0 = evalIdx(test);
        if (r0 && passes(r0.r, th)) {
          found = 0;
        } else if (hi > 0) {
          let lo = 0, up = hi;
          while (lo + 1 < up) {
            const mid = Math.floor((lo + up) / 2);
            let t = cur.slice();
            t[gi] = mid;
            const rr = evalIdx(t);
            if (rr && passes(rr.r, th)) up = mid;
            else lo = mid;
          }
          found = up;
        }

        if (found >= 0 && found < cur[gi]) {
          let trial = cur.slice();
          trial[gi] = found;
          const rr = evalIdx(trial);
          if (rr && passes(rr.r, th)) {
            cur = trial;
            rec = rr;
            best = rr;
            changed = true;
          }
        }
      }
      if (!changed) break;
    }
    return best;
  }

  const thresholds = [
    { u: 0.60, a: 6.0, f: 3.00, sag: 0.65, sway: 0.65 },
    { u: 0.75, a: 4.5, f: 2.80, sag: 0.80, sway: 0.80 },
    { u: 0.90, a: 3.3, f: 2.60, sag: 0.95, sway: 0.95 },
    { u: 1.00, a: 3.05, f: 2.52, sag: 1.00, sway: 1.00 }
  ];

  const natural = groupNames.map((g, i) => i);
  const reverse = natural.slice().reverse();
  const orders = [natural, reverse];

  let chosen = null;

  for (let ti = 0; ti < thresholds.length; ti++) {
    const th = thresholds[ti];
    const results = [];
    for (let oi = 0; oi < orders.length; oi++) {
      if (calls >= callLimit) break;
      const res = optimize(th, orders[oi]);
      if (res && res.r && res.r.ok) results.push(res);
    }
    if (results.length > 0) {
      results.sort((a, b) => {
        const ma = (a.r && typeof a.r.mass === "number") ? a.r.mass : Infinity;
        const mb = (b.r && typeof b.r.mass === "number") ? b.r.mass : Infinity;
        return ma - mb;
      });
      chosen = results[0];
      break;
    }
    if (calls >= callLimit) break;
  }

  if (!chosen) {
    const rec = evalIdx(maxIdx);
    if (rec && rec.r && rec.r.ok) chosen = rec;
  }

  let finalDesign;
  if (chosen && chosen.design) {
    finalDesign = chosen.design;
  } else {
    finalDesign = makeDesign(maxIdx);
  }

  finalDesign.note = "Pinned through-truss box: two 8 m side trusses, top/bottom horizontal bracing, end diaphragms; conservative safety-margin section search.";
  return finalDesign;
}

