      note: "Tied-arch space truss with polygonal ribs, pin joints, and lateral bracing; optimized by section search.",
      nodes: nodes,
      members: members
    };
  }

  const cache = new Map();
  let calls = 0;
  const callLimit = 390;

  function evalIdx(idx) {
    const key = idx.join(",");
    if (cache.has(key)) return cache.get(key);
    if (calls >= callLimit) return null;
    calls++;
    let rec = { idx: idx.slice() };
    try {
