  }

  function coordinateDescent(start, th, order, maxPass) {
    const rec0 = evalIdx(start);
    if (!rec0 || !passes(rec0.r, th)) return null;
    let cur = start.slice();
    let rec = rec0;
    for (let p = 0; p < maxPass; p++) {
      let changed = false;
      for (let oi = 0; oi < order.length; oi++) {
        const gi = order[oi];
        const hi = cur[gi];
        if (hi <= 0) continue;

        let t0 = cur.slice();
        t0[gi] = 0;
        const r0 = evalIdx(t0);
        if (r0 && passes(r0.r, th)) {
          cur = t0; rec = r0; changed = true;
          continue;
        }

        let L = 0, R = hi;
        while (L + 1 < R) {
          const M = (L + R) >> 1;
          const t = cur.slice();
          t[gi] = M;
          const rm = evalIdx(t);
          if (rm && passes(rm.r, th)) R = M;
          else L = M;
          if (calls >= callLimit) break;
        }
        if (R < cur[gi]) {
          const t = cur.slice();
          t[gi] = R;
          const rr = evalIdx(t);
          if (rr && passes(rr.r, th)) {
            cur = t; rec = rr; changed = true;
          }
        }
        if (calls >= callLimit) break;
      }
      if (!changed || calls >= callLimit) break;
    }
    return { idx: cur, rec: rec };
  }

  function solve(th) {
    const orders = [
      [0, 1, 2, 3, 4, 5, 6, 7, 8],
      [8, 7, 6, 5, 4, 3, 2, 1, 0]
    ];
    const candidates = [];
    for (let oi = 0; oi < orders.length; oi++) {
      if (calls >= callLimit) break;
      const maxPass = oi === 0 ? 3 : 2;
      const res = coordinateDescent(baseSeed, th, orders[oi], maxPass);
      if (res) candidates.push(res);
    }
    if (candidates.length === 0) return null;
    candidates.sort((a, b) => a.rec.r.mass - b.rec.r.mass);
    return candidates[0];
  }

  let chosen = null;
  let res = solve(T1);
  if (res) chosen = res;
  else {
    res = solve(T2);
