  }
  if (!chosen) {
    chosen = { idx: baseSeed.slice(), rec: evalIdx(baseSeed) };
  }

  const finalDesign = makeDesign(chosen.idx);
  finalDesign.note = "Tied-arch space truss with polygonal ribs, pin joints, and lateral bracing; optimized by section search.";
