  const groupKeys = [];
  for (let k = 0; k < 4; k++) groupKeys.push("t" + k);   // top chords, symmetric panel pairs
  for (let k = 0; k < 4; k++) groupKeys.push("b" + k);   // bottom chords
  for (let k = 0; k < 4; k++) groupKeys.push("v" + k);   // verticals by distance from ends
  for (let k = 0; k < 4; k++) groupKeys.push("d" + k);   // side diagonals
  for (let k = 0; k < 3; k++) groupKeys.push("f" + k);   // floor beams
  for (let k = 0; k < 3; k++) groupKeys.push("tc" + k);  // top cross beams
  for (let k = 0; k < 3; k++) groupKeys.push("tl" + k);  // top lateral diagonals
  for (let k = 0; k < 3; k++) groupKeys.push("bl" + k);  // bottom lateral diagonals
