  for (let k = 0; k < 4; k++) {
    baseMap["t" + k] = "S690 CHS193.7x8";
    baseMap["b" + k] = "S690 CHS193.7x8";
    baseMap["v" + k] = "S690 CHS273x10";
    baseMap["d" + k] = "S690 CHS273x10";
  }
  for (let k = 0; k < 3; k++) {
    baseMap["f" + k] = "S690 CHS193.7x8";
    baseMap["tl" + k] = "S690 CHS168.3x6.3";
    baseMap["bl" + k] = "S690 CHS273x10";
