  const T = {
    u: 0.78,
    a: 4.2,
    f: 2.70,
    sag: 0.90,
    sway: 0.90,
    fat: 0.70
  };

  function makeDesign(specMap, H) {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({ id: "TL" + i, x: xs[i], y: H, z: -4.05, joint: "pin" });
      nodes.push({ id: "TR" + i, x: xs[i], y: H, z:  4.05, joint: "pin" });
