    }

    // Top cross beams.
    for (let i = 0; i <= 8; i++) {
      const d = Math.min(i, 8 - i);
      const k = d === 0 ? 0 : d === 1 ? 1 : 2;
      add("TL" + i, "TR" + i, "tc" + k);
    }

    // Top lateral diagonals.
    for (let i = 0; i < 8; i++) {
      const kk = Math.min(i, 7 - i);
      const k = kk === 0 ? 0 : kk === 1 ? 1 : 2;
      add("TL" + i, "TR" + (i + 1), "tl" + k);
    }

    // Bottom lateral diagonals.
    for (let i = 0; i < 8; i++) {
      const kk = Math.min(i, 7 - i);
      const k = kk === 0 ? 0 : kk === 1 ? 1 : 2;
      add("L" + i, "R" + (i + 1), "bl" + k);
    }

