    add("L0", "TR0", "end");
    add("R0", "TL0", "end");
    add("L8", "TR8", "end");
    add("R8", "TL8", "end");

    return {
      design: {
        note: "Attempt 5: known through-truss topology with finer section groups and expanded CHS material search (S355/S460/S690/stainless/aluminium), conservative utilisation/frequency margins.",
        nodes: nodes,
        members: members
      },
      infos: infos
    };
  }

  const CALL_LIMIT = 392;
  let calls = 0;
  const cache = new Map();

  function evalDesign(specMap, H) {
    const key = String(H) + "|" + groupKeys.map(g => specMap[g]).join("|");
    if (cache.has(key)) return cache.get(key);
    if (calls >= CALL_LIMIT) return null;

