  function passes(r, th) {
    if (!r || !r.ok) return false;
    if (r.failure) {
      const f = String(r.failure).toLowerCase();
      if (f && f !== "false" && f !== "none" && f !== "null" && f !== "undefined") {
        return false;
      }
    }
    if (typeof r.maxUtil === "number" && r.maxUtil > th.u) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < th.a) return false;
    if (typeof r.frequency === "number" && r.frequency < th.f) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" &&
        r.sag > th.sag * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" &&
        r.sway > th.sway * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > th.fat) return false;
    if (r.robustness === false) return false;
    if (typeof r.robustness === "string" && /fail|false|no/i.test(r.robustness)) return false;
    return true;
  }

  function computeGroupLengths(rec) {
    const coords = {};
    for (let i = 0; i < xs.length; i++) {
      coords["L" + i] = { x: xs[i], y: 0, z: -4.05 };
      coords["R" + i] = { x: xs[i], y: 0, z:  4.05 };
    }
    const nodes = rec.design.nodes || [];
    for (let i = 0; i < nodes.length; i++) {
      const n = nodes[i];
      coords[n.id] = { x: n.x, y: n.y, z: n.z };
    }
    const len = {};
    for (let i = 0; i < rec.infos.length; i++) {
      const info = rec.infos[i];
      const p = coords[info.a];
      const q = coords[info.b];
      if (!p || !q) continue;
      const L = Math.hypot(p.x - q.x, p.y - q.y, p.z - q.z);
      len[info.g] = (len[info.g] || 0) + L;
    }
    return len;
  }

  // Try the slightly taller truss first; fall back to the known attempt-4 height.
  let currentH = 8.3;
  let currentMap = Object.assign({}, baseMap);
  let currentRec = evalDesign(currentMap, currentH);

  if (!currentRec || !passes(currentRec.r, T)) {
    const rec80 = evalDesign(currentMap, 8.0);
    if (rec80 && passes(rec80.r, T)) {
      currentH = 8.0;
      currentRec = rec80;
    } else {
      // Known-safe fallback: attempt-4 geometry/sections.
      const md = makeDesign(baseMap, 8.0);
      return md.design;
    }
  }

  let groupLens = computeGroupLengths(currentRec);
  let bestRec = currentRec;
  let bestMap = Object.assign({}, currentMap);
  let bestH = currentH;

  function makeOrder(map) {
    return groupKeys.slice().sort((a, b) => {
      const ma = (groupLens[a] || 0) * (massPerSpec[map[a]] || 0);
      const mb = (groupLens[b] || 0) * (massPerSpec[map[b]] || 0);
      return mb - ma;
    });
  }

  function optimizeGroup(g, doAL) {
    const curSpec = currentMap[g];
    const curIdx = candIndex.get(curSpec);
    if (curIdx === undefined || curIdx <= 0) return false;

    let bestIdx = curIdx;
    let bestRecLocal = currentRec;
    let changed = false;

    function test(idx) {
      if (idx >= curIdx) return true;
      const spec = candidateSpecs[idx];
      if (!spec || spec === currentMap[g]) return true;

      const m = Object.assign({}, currentMap);
      m[g] = spec;
      const rr = evalDesign(m, currentH);
      if (!rr || !rr.r) return false;

      const ok = passes(rr.r, T);
      if (ok && typeof rr.r.mass === "number" &&
          typeof bestRecLocal.r.mass === "number" &&
          rr.r.mass < bestRecLocal.r.mass - 1e-9) {
        bestIdx = idx;
        bestRecLocal = rr;
        changed = true;
      }
      return ok;
    }

    if (curIdx > 0) {
      const p0 = test(0);
      if (!p0) {
        let low = 0;
        let high = curIdx;
        let guard = 0;
        while (high - low > 1 && calls < CALL_LIMIT - 5 && guard++ < 25) {
          const mid = (low + high) >> 1;
          if (test(mid)) high = mid;
          else low = mid;
        }
      }
    }

    // Scan a short window below the best known passing point.
    for (let rep = 0; rep < 2; rep++) {
      const start = Math.max(0, bestIdx - 4);
      for (let idx = start; idx < bestIdx; idx++) {
        if (calls >= CALL_LIMIT - 3) break;
        test(idx);
      }
    }

    // Separately probe high-strength aluminium for higher-mass groups where it may be missed
    // by monotone mass ordering due to its different stiffness/strength trade-off.
    if (doAL && calls < CALL_LIMIT - 5) {
      const alIdxs = [];
      for (let j = 0; j < alIndicesAll.length; j++) {
        const idx = alIndicesAll[j];
        if (idx < curIdx) alIdxs.push(idx);
      }
      if (alIdxs.length > 0) {
        let low = -1;
        let high = alIdxs.length;
        while (high - low > 1 && calls < CALL_LIMIT - 5) {
          const mid = (low + high) >> 1;
          if (test(alIdxs[mid])) high = mid;
          else low = mid;
        }
        const lo2 = Math.max(0, high - 3);
        const hi2 = Math.min(alIdxs.length, high);
        for (let j = lo2; j < hi2; j++) {
          if (calls >= CALL_LIMIT - 3) break;
          test(alIdxs[j]);
        }
      }
    }

    if (changed && bestRecLocal && passes(bestRecLocal.r, T)) {
      currentMap = Object.assign({}, bestRecLocal.specMap);
      currentRec = bestRecLocal;
      return true;
    }
    return false;
  }

  // First broad coordinate-descent pass.
  let order = makeOrder(currentMap);
  for (let i = 0; i < order.length; i++) {
    if (calls >= CALL_LIMIT - 15) break;
    optimizeGroup(order[i], false);
  }

  // Further passes after earlier reductions changed the global stiffness/mass balance.
  for (let pass = 0; pass < 2; pass++) {
    if (calls >= CALL_LIMIT - 15) break;
    order = makeOrder(currentMap);
    let anyChange = false;
    for (let i = 0; i < order.length; i++) {
      if (calls >= CALL_LIMIT - 12) break;
      const g = order[i];
      const old = currentMap[g];
      optimizeGroup(g, false);
      if (currentMap[g] !== old) anyChange = true;
    }
    if (!anyChange) break;
  }

  // Targeted aluminium probes on the largest remaining groups.
  if (calls < CALL_LIMIT - 12) {
    order = makeOrder(currentMap).slice(0, 14);
    for (let i = 0; i < order.length; i++) {
      if (calls >= CALL_LIMIT - 8) break;
      optimizeGroup(order[i], true);
    }
  }

  bestRec = currentRec;
  bestMap = Object.assign({}, currentMap);
  bestH = currentH;

  // Sometimes the same optimised sections can be slightly lighter at a smaller depth
  // while still retaining the conservative nominal margins.
  let chosenRec = bestRec;
  let chosenH = bestH;
  const hTry = [8.0, 8.1, 8.2, 8.25, 8.31];

  for (let ih = 0; ih < hTry.length; ih++) {
    if (calls >= CALL_LIMIT) break;
    const h = hTry[ih];
    if (Math.abs(h - chosenH) < 1e-9) continue;

    const rr = evalDesign(bestMap, h);
    if (rr && passes(rr.r, T) &&
        typeof rr.r.mass === "number" &&
        typeof chosenRec.r.mass === "number" &&
        rr.r.mass < chosenRec.r.mass - 1e-9) {
      chosenRec = rr;
      chosenH = h;
    }
  }

  if (chosenRec && chosenRec.design) return chosenRec.design;

  // Final fallback.
  const md = makeDesign(bestMap, bestH);
  return md.design;
}

