    for (let idx = 0; idx < md.design.members.length; idx++) {
      const [a, b] = md.design.members[idx];
      const p = coords[a];
      const q = coords[b];
      if (!p || !q) continue;
      const L = Math.hypot(p.x - q.x, p.y - q.y, p.z - q.z);
      const g = md.infos[idx].g;
      groupLengths[g] = (groupLengths[g] || 0) + L;
    }

