    if (typeof r.alphaCr === "number" && r.alphaCr < T.a) return false;
    if (typeof r.frequency === "number" && r.frequency < T.f) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > T.sag * r.sagLimit) return false;
