      // Note: build called twice above to keep design; minor overhead is OK and analyse already used first.
      // To avoid inconsistency, re-build once and use it:
      rec.design = build(map);
      localCache.set(key, rec);
      return rec;
    }
    // build seed design to compute group lengths
    const seedDesign = build(seedMap);
    const coords = Object.assign({}, deckCoords);
    for (const n of seedDesign.nodes) coords[n.id] = { x: n.x, y: n.y, z: n.z };
    const groupLengths = {};
    for (let i = 0; i < seedDesign.members.length; i++) {
      const [a, b] = seedDesign.members[i];
      const p = coords[a], q = coords[b];
      if (!p || !q) continue;
      const L = Math.hypot(p.x - q.x, p.y - q.y, p.z - q.z);
      const g = memberGroups[i];
      groupLengths[g] = (groupLengths[g] || 0) + L;
    }
    const groups = [...new Set(memberGroups)];
    let currentMap = Object.assign({}, seedMap);
    let currentRec = evalRec(currentMap);
    if (!currentRec || !passes(currentRec.r, T)) return null;
    let bestRec = currentRec;
    const groupMass = (g, map) => (groupLengths[g] || 0) * (candMpl.get(map[g]) || 0);
    for (let pass = 0; pass < 3; pass++) {
      if (calls >= 400) break;
      let any = false;
      groups.sort((a, b) => groupMass(b, currentMap) - groupMass(a, currentMap));
      for (const g of groups) {
        if (calls >= 400) break;
        const curSpec = currentMap[g];
        const curIdx = candIndex.get(curSpec);
        if (curIdx === undefined || curIdx <= 0) continue;
        let bestIdx = curIdx;
        function testIdx(idx) {
          if (idx >= curIdx) return true;
          if (calls >= 400) return false;
          const spec = cand[idx].spec;
          if (!spec || spec === currentMap[g]) return true;
          const m = Object.assign({}, currentMap, { [g]: spec });
          const rec = evalRec(m);
          return !!(rec && passes(rec.r, T));
        }
        if (testIdx(0)) {
          bestIdx = 0;
        } else {
          let low = 0, high = curIdx;
          while (high - low > 1 && calls < 400) {
            const mid = (low + high) >> 1;
            if (testIdx(mid)) high = mid; else low = mid;
          }
          for (let idx = Math.max(0, high - 6); idx < high; idx++) {
            if (calls >= 400) break;
            if (testIdx(idx)) { high = idx; break; }
          }
          bestIdx = high;
        }
        if (bestIdx < curIdx) {
          const spec = cand[bestIdx].spec;
          const m = Object.assign({}, currentMap, { [g]: spec });
          const rec = evalRec(m);
          if (rec && passes(rec.r, T)) {
            currentMap = m;
            currentRec = rec;
            any = true;
            if (rec.r.mass < bestRec.r.mass) bestRec = rec;
          }
        }
      }
      if (!any || calls >= 400) break;
    }
    return bestRec;
  }

  // ---------------- known-good fallback design ----------------
  const fallbackDesign = {
