      {"id":"TL7","x":27.738,"y":8,"z":-4.05,"joint":"pin"},{"id":"TR7","x":27.738,"y":8,"z":4.05,"joint":"pin"},
      {"id":"TL8","x":31.7,"y":8,"z":-4.05,"joint":"pin"},{"id":"TR8","x":31.7,"y":8,"z":4.05,"joint":"pin"}
    ],
    "members": [
      ["TL0","TL1","AL6082 CHS273x10"],["TR0","TR1","AL6082 CHS273x10"],["TL1","TL2","AL6082 CHS273x10"],["TR1","TR2","AL6082 CHS273x10"],
