      ["TL4","TR4","S690 CHS139.7x5"],["TL5","TR5","S690 CHS139.7x5"],["TL6","TR6","S690 CHS139.7x5"],["TL7","TR7","S690 CHS139.7x5"],
      ["TL8","TR8","AL7075 CHS42.4x3.2"],
      ["TL0","TR1","S690 CHS168.3x6.3"],["TL1","TR2","S690 CHS168.3x6.3"],["TL2","TR3","S690 CHS168.3x5"],["TL3","TR4","S690 CHS168.3x5"],
      ["TL4","TR5","S690 CHS168.3x5"],["TL5","TR6","S690 CHS168.3x5"],["TL6","TR7","S690 CHS168.3x6.3"],["TL7","TR8","S690 CHS168.3x6.3"],
      ["L0","R1","S690 CHS273x10"],["L1","R2","S690 CHS273x10"],["L2","R3","S690 CHS273x10"],["L3","R4","S690 CHS273x10"],
      ["L4","R5","S690 CHS273x10"],["L5","R6","S690 CHS273x10"],["L6","R7","S690 CHS273x10"],["L7","R8","S690 CHS273x10"],
      ["L0","TR0","S690 CHS193.7x8"],["R0","TL0","S690 CHS193.7x8"],["L8","TR8","S690 CHS193.7x8"],["R8","TL8","S690 CHS193.7x8"]
    ]
  };

  // evaluate fallback once to obtain nominal mass (should be ~25147)
  let fallbackMass = 25147;
  try {
    const fr = analyse(fallbackDesign);
    calls++;
    if (fr && typeof fr.mass === "number") fallbackMass = fr.mass;
  } catch (e) {}

  // ---------------- search bowstring arch ----------------
  let seedMap = null;
  let Tuse = null;
  const seedSpecs = [
    "S690 CHS273x10",
    "S690 CHS323.9x10",
    "S690 CHS355.6x12.5",
    "S690 CHS406.4x12.5",
    "S690 CHS457x16"
  ];
  const seedRecs = [];
  for (const spec of seedSpecs) {
    if (calls >= 400) break;
    const map = {};
    for (const g of archGroups) map[g] = spec;
    let r = null;
    try { r = analyse(buildArch(map)); } catch (e) { r = { ok: false, error: String(e) }; }
    calls++;
    seedRecs.push({ map, r });
    if (r && passes(r, Tstrict)) { seedMap = map; Tuse = Tstrict; break; }
  }
  if (!seedMap) {
    for (const { map, r } of seedRecs) {
      if (r && passes(r, Tsearch)) { seedMap = map; Tuse = Tsearch; break; }
    }
  }
  let bestArch = null;
  if (seedMap && calls < 400) {
    bestArch = runOptimize("arch", buildArch, archMemberGroups, seedMap, Tuse, 400 - calls);
  }

  // ---------------- choose final ----------------
  if (bestArch && bestArch.r && passes(bestArch.r, Tuse)) {
    const useArch = (Tuse === Tstrict)
      ? bestArch.r.mass < fallbackMass
      : bestArch.r.mass < 0.90 * fallbackMass;
    if (useArch) {
      return {
        note: "Bowstring arch below deck, optimized " + (Tuse === Tstrict ? "with strict safety margins" : "with moderate safety margins") + ".",
        nodes: bestArch.design.nodes,
        members: bestArch.design.members
      };
    }
  }
  return fallbackDesign;
}

function design(site, analyse) {
  const t0 = Date.now();
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  // Deep twin truss: top chord above the traffic envelope (y 8.2), bottom chord below the deck (y -5.6).
  // Deck nodes sit at mid-depth, so the truss depth is ~13.8 m and chord forces are about M/13.8.
  const YT = 8.2, YB = -5.6, ZL = -4.05, ZR = 4.05;
  // Circular hollow sections, ordered by area (index = size level)
  const CH = ['CHS60.3x4','CHS76.1x4','CHS88.9x5','CHS114.3x5','CHS139.7x5','CHS139.7x6.3',
              'CHS168.3x6.3','CHS193.7x6.3','CHS193.7x8','CHS219.1x8','CHS244.5x8','CHS273x10',
              'CHS323.9x10','CHS355.6x12.5','CHS406.4x12.5','CHS457x16'];
  const GROUPS = ['TOP','BOT','DECK','PT','PB','DT','DB','DX','LT','LB'];

  const nodes = [];
  for (let i = 0; i < 9; i++) {
    nodes.push({id:'TL'+i, x:xs[i], y:YT, z:ZL, joint:'pin'});
    nodes.push({id:'TR'+i, x:xs[i], y:YT, z:ZR, joint:'pin'});
    nodes.push({id:'BL'+i, x:xs[i], y:YB, z:ZL, joint:'pin'});
    nodes.push({id:'BR'+i, x:xs[i], y:YB, z:ZR, joint:'pin'});
  }

  const M = []; // [a, b, group]
  const add = (a, b, g) => M.push([a, b, g]);
  for (const s of ['L', 'R']) {
    const T = 'T' + s, B = 'B' + s;
    for (let i = 0; i < 8; i++) {
      add(T+i, T+(i+1), 'TOP');
      add(B+i, B+(i+1), 'BOT');
      add(s+i, s+(i+1), 'DECK');
    }
    for (let i = 0; i < 9; i++) {
      add(s+i, T+i, 'PT');
      add(s+i, B+i, 'PB');
    }
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) { add(s+i, T+(i+1), 'DT'); add(s+i, B+(i+1), 'DB'); }
      else             { add(T+i, s+(i+1), 'DT'); add(B+i, s+(i+1), 'DB'); }
    }
  }
  for (let i = 0; i < 9; i++) {
    add('L'+i, 'R'+i, 'DX');          // deck-level cross girders (on the bottom face of the envelope)
    add('TL'+i, 'TR'+i, 'LT');        // top lateral struts
    add('BL'+i, 'BR'+i, 'LB');        // bottom lateral struts
  }
  for (let i = 0; i < 8; i++) {
    add('TL'+i, 'TR'+(i+1), 'LT'); add('TR'+i, 'TL'+(i+1), 'LT');
    add('BL'+i, 'BR'+(i+1), 'LB'); add('BR'+i, 'BL'+(i+1), 'LB');
  }

  let calls = 0;

  function evalIdx(mat, idx) {
    calls++;
    const members = M.map(m => [m[0], m[1], mat + ' ' + CH[idx[m[2]]]]);
    const d = {note: 'Deep twin Warren truss (top y 8.2, bottom y -5.6), pinned, lateral top/bottom bracing and deck cross girders; ' + mat + ' CHS sized per group', nodes: nodes.map(n => Object.assign({}, n)), members: members};
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) return null;
    return {r: r, d: d};
  }

  function gUtil(r) {
    if (!r || !Array.isArray(r.members) || r.members.length !== M.length) return null;
    const gu = {};
    GROUPS.forEach(g => gu[g] = 0);
    r.members.forEach((m, i) => {
      const u = (m && typeof m.util === 'number') ? m.util : 0;
      const g = M[i][2];
      if (u > gu[g]) gu[g] = u;
    });
    return gu;
  }

  function search(mat, start, lim) {
    const n = CH.length;
    const stop = calls + lim;
    const ok = () => calls < stop && (Date.now() - t0) < 70000;
    let cur = {};
    GROUPS.forEach(g => cur[g] = start);
    let e = evalIdx(mat, cur);
    while ((!e || !e.r.ok) && ok()) {
      let any = false;
      GROUPS.forEach(g => { if (cur[g] < n - 1) { cur[g]++; any = true; } });
      if (!any) return null;
      e = evalIdx(mat, cur);
    }
    if (!e || !e.r.ok) return null;
    let best = {mass: e.r.mass, d: e.d};
    let gu = gUtil(e.r);
    let improved = true;
    while (improved && ok()) {
      improved = false;
      const order = GROUPS.slice().sort((a, b) => (gu ? gu[a] : 0) - (gu ? gu[b] : 0));
      for (const g of order) {
        if (!ok()) break;
        if (cur[g] <= 0) continue;
        if (gu && gu[g] > 0.92) continue;
        const trial = Object.assign({}, cur);
        trial[g] -= 1;
        const t = evalIdx(mat, trial);
        if (t && t.r.ok) {
          cur = trial;
          gu = gUtil(t.r);
          improved = true;
          if (typeof t.r.mass === 'number' && (typeof best.mass !== 'number' || t.r.mass < best.mass)) {
            best = {mass: t.r.mass, d: t.d};
          }
        }
      }
    }
    return best;
  }

  const a = search('AL7075', 8, 180);
  const b = search('S355', 11, 180);
  let pick = null;
  for (const c of [a, b]) {
    if (c && (!pick || (typeof c.mass === 'number' && c.mass < pick.mass))) pick = c;
  }
  if (pick) return pick.d;

  return {
    note: 'fallback: heavy S355 deep truss (no search result passed)',
    nodes: nodes,
    members: M.map(m => [m[0], m[1], 'S355 CHS457x16'])
  };
}

function design(site, analyse) {
  const t0 = Date.now();
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const YT = 8.2, YB = -5.6, ZL = -4.05, ZR = 4.05;
  const MAT = 'AL7075';
  // AL7075 CHS, ascending by area
  const CH = ['CHS48.3x3.2','CHS60.3x3.2','CHS60.3x4','CHS76.1x3.2','CHS76.1x4','CHS88.9x4',
              'CHS88.9x5','CHS114.3x4','CHS114.3x5','CHS139.7x5','CHS168.3x5','CHS139.7x6.3',
              'CHS168.3x6.3','CHS193.7x6.3','CHS193.7x8','CHS219.1x8','CHS244.5x8','CHS273x10',
              'CHS323.9x10','CHS355.6x12.5','CHS406.4x12.5','CHS457x16'];
