          best = {mass: t.mass, d: t.d};
        }
      }
    }
  }
  return best.d;
}

function design(site, analyse) {
  const t0 = Date.now();
  const xs = [0, 3.963, 7.925, 11.888, 15.85, 19.813, 23.775, 27.738, 31.7];
  const YT = 8.2, YB = -5.6, ZL = -4.05, ZR = 4.05;

  // ---- own nodes; positions of all nodes including the fixed deck nodes
  const nodes = [];
  const P = {};
  for (let i = 0; i < 9; i++) {
    const spec = [['TL', YT, ZL], ['TR', YT, ZR], ['BL', YB, ZL], ['BR', YB, ZR]];
    for (const [p, y, z] of spec) {
      nodes.push({id: p + i, x: xs[i], y: y, z: z, joint: 'pin'});
      P[p + i] = [xs[i], y, z];
    }
    P['L' + i] = [xs[i], 0, ZL];
    P['R' + i] = [xs[i], 0, ZR];
  }
  const ids = Object.keys(P);
  const N = ids.length;
  const idx = {};
  ids.forEach((n, k) => { idx[n] = k; });

  // ---- base bracing: triangulated side trusses, top/bottom laterals, deck X-bracing, end frames
  const M = [];
  const add = (a, b, g) => M.push([a, b, g]);
  for (const s of ['L', 'R']) {
    const T = 'T' + s, B = 'B' + s;
    for (let i = 0; i < 8; i++) {
      add(T + i, T + (i + 1), 'TC');
      add(B + i, B + (i + 1), 'BC');
      add(s + i, s + (i + 1), 'DC');
      add(T + i, s + (i + 1), 'DU');
      add(s + i, B + (i + 1), 'DL');
    }
    for (let i = 0; i < 9; i++) {
      add(s + i, T + i, 'VT');
      add(s + i, B + i, 'VB');
    }
  }
  for (let i = 0; i < 9; i++) {
    add('TL' + i, 'TR' + i, 'LTS');
    add('BL' + i, 'BR' + i, 'LBS');
    add('L' + i, 'R' + i, 'DX');
  }
  for (let i = 0; i < 8; i++) {
    add('TL' + i, 'TR' + (i + 1), 'LTD');
    add('BL' + i, 'BR' + (i + 1), 'LBD');
    add('L' + i, 'R' + (i + 1), 'DDX');
  }
  add('TL0', 'R0', 'END'); add('BL0', 'R0', 'END');
  add('TL8', 'R8', 'END'); add('BL8', 'R8', 'END');

  // ---- free degrees of freedom (bearings hold the listed directions)
  const fixed = new Set();
  const fx = (n, c) => fixed.add(3 * idx[n] + c);
  fx('L0', 0); fx('L0', 1); fx('L0', 2);
  fx('R0', 0); fx('R0', 1);
  fx('L8', 1); fx('L8', 2);
  fx('R8', 1);
  const col = new Array(3 * N).fill(-1);
  let nc = 0;
  for (let k = 0; k < 3 * N; k++) if (!fixed.has(k)) col[k] = nc++;

  function rowOf(a, b) {
    const pa = P[a], pb = P[b];
    const d = [pb[0] - pa[0], pb[1] - pa[1], pb[2] - pa[2]];
    const L = Math.hypot(d[0], d[1], d[2]);
    const r = new Float64Array(nc);
    for (let c = 0; c < 3; c++) {
      const u = d[c] / L;
      const ka = col[3 * idx[a] + c], kb = col[3 * idx[b] + c];
      if (ka >= 0) r[ka] -= u;
      if (kb >= 0) r[kb] += u;
    }
    return r;
  }

  // Gram-Schmidt basis of the row space of the rigidity matrix
  const Q = [];
  function addRow(r) {
    const v = Float64Array.from(r);
    for (let pass = 0; pass < 2; pass++) {
      for (const q of Q) {
        let dot = 0;
        for (let j = 0; j < nc; j++) dot += q[j] * v[j];
        if (dot !== 0) for (let j = 0; j < nc; j++) v[j] -= dot * q[j];
      }
    }
    let s = 0;
    for (let j = 0; j < nc; j++) s += v[j] * v[j];
    s = Math.sqrt(s);
    if (s < 1e-7) return false;
    for (let j = 0; j < nc; j++) v[j] /= s;
    Q.push(v);
    return true;
  }
  for (const m of M) addRow(rowOf(m[0], m[1]));

  // ---- geometry helpers for completion
  const dist = (a, b) => {
    const p = P[a], q = P[b];
    return Math.hypot(q[0] - p[0], q[1] - p[1], q[2] - p[2]);
  };
  const key = (a, b) => (a < b ? a + '|' + b : b + '|' + a);
  const adj = {};
  ids.forEach(n => { adj[n] = []; });
  const have = new Set();
  M.forEach(m => {
    adj[m[0]].push(m[1]); adj[m[1]].push(m[0]);
    have.add(key(m[0], m[1]));
  });
  function throughBox(a, b) {
    // traffic envelope x 0..31.7, y 0..5.2, z -4.05..4.05 (faces allowed)
    const pa = P[a], pb = P[b];
    for (let k = 1; k < 60; k++) {
      const t = k / 60;
      const x = pa[0] + t * (pb[0] - pa[0]);
      const y = pa[1] + t * (pb[1] - pa[1]);
      const z = pa[2] + t * (pb[2] - pa[2]);
      if (x > 0.02 && x < 31.68 && y > 0.02 && y < 5.18 && z > -4.03 && z < 4.03) return true;
    }
    return false;
  }
  const cos12 = Math.cos(12 * Math.PI / 180);
  function angleOK(a, b) {
    for (const [n, o] of [[a, b], [b, a]]) {
      if (adj[n].length >= 12) return false;
      const u = [P[o][0] - P[n][0], P[o][1] - P[n][1], P[o][2] - P[n][2]];
      const lu = Math.hypot(u[0], u[1], u[2]);
      for (const c of adj[n]) {
        const w = [P[c][0] - P[n][0], P[c][1] - P[n][1], P[c][2] - P[n][2]];
        const lw = Math.hypot(w[0], w[1], w[2]);
        const cs = (u[0] * w[0] + u[1] * w[1] + u[2] * w[2]) / (lu * lw);
        if (cs > cos12) return false;
      }
    }
    return true;
  }

  // ---- complete the bracing until the rigidity matrix has full rank (no translational mechanism)
  const cands = [];
  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      const a = ids[i], b = ids[j];
      if (have.has(key(a, b))) continue;
      const L = dist(a, b);
      if (L < 0.5 || L > 11.5) continue;
      if (throughBox(a, b)) continue;
      cands.push([a, b, L]);
    }
  }
  cands.sort((p, q) => p[2] - q[2]);
  for (const [a, b] of cands) {
    if (Q.length >= nc) break;
    if (!angleOK(a, b)) continue;
    if (addRow(rowOf(a, b))) {
      M.push([a, b, 'XT']);
      adj[a].push(b); adj[b].push(a);
      have.add(key(a, b));
    }
  }

  // ---- section options: CHS in AL7075 and S690 (mass per metre in kg/m)
  const CH = [
    ['CHS33.7x2.6', 2.54], ['CHS42.4x3.2', 3.94], ['CHS48.3x3.2', 4.53], ['CHS60.3x3.2', 5.74],
    ['CHS60.3x4', 7.07], ['CHS76.1x3.2', 7.33], ['CHS76.1x4', 9.06], ['CHS88.9x4', 10.67],
    ['CHS88.9x5', 13.18], ['CHS114.3x4', 13.86], ['CHS114.3x5', 17.17], ['CHS139.7x5', 21.16],
    ['CHS139.7x6.3', 26.4], ['CHS168.3x5', 25.65], ['CHS168.3x6.3', 32.06], ['CHS193.7x6.3', 37.09],
    ['CHS193.7x8', 46.67], ['CHS219.1x8', 53.06], ['CHS244.5x8', 59.44], ['CHS273x10', 82.62],
    ['CHS323.9x10', 98.61], ['CHS355.6x12.5', 134.74], ['CHS406.4x12.5', 154.68], ['CHS457x16', 221.67]
  ];
  const OPTS = [];
  for (const [nm, A] of CH) {
    OPTS.push({name: 'AL7075 ' + nm, m: 2810 * A * 1e-4});
    OPTS.push({name: 'S690 ' + nm, m: 7850 * A * 1e-4});
  }
  OPTS.sort((p, q) => p.m - q.m);
  const NO = OPTS.length;

  const G = [];
  M.forEach(m => { if (G.indexOf(m[2]) < 0) G.push(m[2]); });
  const lens = M.map(m => dist(m[0], m[1]));
  const estMass = cfg => {
    let s = 0;
    M.forEach((m, i) => { s += lens[i] * OPTS[cfg[m[2]]].m; });
    return s;
  };

  let calls = 0;
  const LIM_CALLS = 370, LIM_MS = 70000;
  const timeUp = () => (Date.now() - t0) > LIM_MS || calls >= LIM_CALLS;

  const mkDesign = cfg => ({
    note: 'Rank-completed 3D pinned Warren box truss with deck X-bracing, top/bottom laterals and end frames; AL7075/S690 CHS sized per group',
    nodes: nodes.map(n => Object.assign({}, n)),
    members: M.map(m => [m[0], m[1], OPTS[cfg[m[2]]].name])
  });

  function ev(cfg) {
    calls++;
    const d = mkDesign(cfg);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) return {ok: false, r: null, d: d, mass: Infinity};
    const ok = !!r.ok && (typeof r.maxUtil !== 'number' || r.maxUtil <= 0.85);
    const mass = (typeof r.mass === 'number') ? r.mass : estMass(cfg);
    return {ok: ok, r: r, d: d, mass: mass};
  }

  function gUtil(r) {
    const gu = {};
    G.forEach(g => { gu[g] = 0; });
    if (r && Array.isArray(r.members) && r.members.length === M.length) {
      r.members.forEach((mm, i) => {
        const u = (mm && typeof mm.util === 'number') ? mm.util : 0;
        if (u > gu[M[i][2]]) gu[M[i][2]] = u;
      });
    }
    return gu;
  }

  // ---- start from a moderate size everywhere and climb until the design passes
  let startIdx = OPTS.findIndex(o => o.m >= 12);
  if (startIdx < 0) startIdx = NO - 1;
  let cur = {};
  G.forEach(g => { cur[g] = startIdx; });
  let e = ev(cur);
  while (!e.ok && !timeUp()) {
    let any = false;
    G.forEach(g => {
      if (cur[g] < NO - 1) { cur[g] = Math.min(NO - 1, cur[g] + 2); any = true; }
    });
    if (!any) break;
    e = ev(cur);
  }
  if (!e.ok) return e.d;

  // ---- greedy descent per group, keeping only passing designs with utilisation margin
  let best = {mass: e.mass, d: e.d, cfg: Object.assign({}, cur)};
  let r = e.r;
  for (const step of [3, 2, 1]) {
    let improved = true;
    while (improved && !timeUp()) {
      improved = false;
      let gu = gUtil(r);
      const order = G.slice().sort((a, b) => gu[a] - gu[b]);
      for (const g of order) {
        if (timeUp()) break;
        if (cur[g] - step < 0) continue;
        if (gu[g] > 0.9) continue;
        const trial = Object.assign({}, cur);
        trial[g] -= step;
        const t = ev(trial);
        if (t.ok && t.mass < best.mass) {
          cur = trial;
          r = t.r;
          best = {mass: t.mass, d: t.d, cfg: Object.assign({}, trial)};
          gu = gUtil(r);
          improved = true;
        }
      }
    }
  }
  return best.d;
}

