    if (!r || r.error) break;

    if (r.ok && typeof r.mass === 'number' &&
        (typeof r.maxUtil !== 'number' || r.maxUtil <= ACCEPT)) {
      if (!best || r.mass < best.mass) best = {mass: r.mass, d: d};
    }

    // stiffness / global stability deficits: grow every member a little
    const over = (a, b) => typeof a === 'number' && typeof b === 'number' && a > b;
    let stiff = false;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < r.fMin) stiff = true;
    if (over(r.sway, r.swayLimit) || over(r.sag, r.sagLimit)) stiff = true;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < r.alphaCrMin) stiff = true;

    // fully stressed update: area scales with utilisation (fatigue, tension, buckling)
    const mu = Array.isArray(r.members) ? r.members : [];
