      });
    }
    if (newCfg.every((v, i) => v === cfg[i])) break;
    cfg = newCfg;
  }

  if (best) return {note: best.d.note, nodes: best.d.nodes, members: best.d.members};
  return last ? last : mk(cfg);
}

