    }
    if (num(r.sway) && num(r.swayLimit) && r.sway > 0.8 * r.swayLimit) {
      dG = Math.max(dG, Math.min(1.3, r.sway / (0.6 * r.swayLimit)));
    }
    if (num(r.sag) && num(r.sagLimit) && r.sag > 0.8 * r.sagLimit) {
