    arr.forEach(e => { if (e && e.id !== undefined) byId[String(e.id)] = e; });
    return M.map((m, i) => {
      const e = byId[m[0] + '-' + m[1]] || byId[m[1] + '-' + m[0]] || arr[i];
      return (e && num(e.util)) ? e.util : 0;
    });
  };

  const umaxG = r => {
    const u = utilOf(r);
    const mx = GROUPS.map(() => 0);
    M.forEach((m, i) => { if (u[i] > mx[GI[i]]) mx[GI[i]] = u[i]; });
    return mx;
  };

  const evalG = gi => {
    const key = gi.join(',');
    if (cache.has(key)) return cache.get(key);
    if (!timeOK()) return null;
    const d = mk(gi);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    calls++;
    if (!r || r.error) { cache.set(key, null); return null; }
    const feas = feasible(r);
    const res = {gi: gi.slice(), r: r, feas: feas, mass: num(r.mass) ? r.mass : Infinity, d: d};
    cache.set(key, res);
    if (feas && num(r.mass) && (!best || res.mass < best.mass)) best = res;
    return res;
  };

  // baseline: uniform AL7075 CHS355.6x12.5 (passed in attempt 7)
  const init = GROUPS.map(() => idx355);
  const base = evalG(init);
  if (!base) return mk(init);

  // phase 1: fully-stressed jump from group utilisation
  let x = null;
  {
    const mx = umaxG(base.r);
    const jump = base.gi.map((k, g) => idxOfArea(CH[k][1] * Math.max(mx[g], 0.02) / TGT));
    x = evalG(jump);
  }

  // phase 2: repair (utilisation bumps first, else stiffness-probed bumps)
  for (let k = 0; k < 12 && x && !x.feas && timeOK(); k++) {
    const r = x.r;
    const mx = umaxG(r);
    const next = x.gi.slice();
    let moved = false;
    if (num(r.maxUtil) && r.maxUtil > TGT) {
      for (let g = 0; g < GROUPS.length; g++) {
        if (mx[g] > TGT && next[g] < NC - 1) { next[g] += 1; moved = true; }
      }
    }
    if (moved) { x = evalG(next); continue; }
    let bestC = null, bestGain = -Infinity;
    for (let g = 0; g < GROUPS.length && timeOK(); g++) {
      if (x.gi[g] >= NC - 1) continue;
      const gi4 = x.gi.slice(); gi4[g] += 1;
      const c4 = evalG(gi4);
      if (!c4) break;
      const df = (num(c4.r.frequency) && num(r.frequency)) ? (c4.r.frequency - r.frequency) : 0;
      const dm = Math.max(1e-6, c4.mass - x.mass);
      const gain = df / dm;
      if (!bestC || gain > bestGain) { bestC = c4; bestGain = gain; }
    }
    if (!bestC) break;
    x = bestC;
  }

  // phase 3: greedy trimming from the best feasible design (step 1, then step 2)
  const trim = step => {
    for (let round = 0; round < 30 && best && timeOK(); round++) {
      const cur = best;
      let bc = null;
      for (let g = 0; g < GROUPS.length && timeOK(); g++) {
        if (cur.gi[g] - step < 0) continue;
        const gi5 = cur.gi.slice(); gi5[g] -= step;
        const c5 = evalG(gi5);
        if (c5 && c5.feas && c5.mass < cur.mass && (!bc || c5.mass < bc.mass)) bc = c5;
      }
      if (!bc) break;
      best = bc;
    }
  };
  trim(1);
  trim(2);
  trim(1);

  if (best) return {note: NOTE, nodes: best.d.nodes, members: best.d.members};
  return mk(init);
}
